    /// 🔁️ Drives the same bounded continuation and exact ACK protocol as the plugin host.
    ///
    /// 📄️ EVERY presented page, not one per turn: `has_pending_typed_operations` counts the
    /// effect/event/ui/completion outboxes and the mounted operations, but NOT a presented
    /// page waiting for its ACK — so a turn that leaves a second page queued can be the turn
    /// the loop exits on, and that page is never seen. A command that publishes an artifact,
    /// a config and an app transient reported two of the three
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    ///
    /// 🧩️ The composed lane rides the same bounded outbox and is counted by
    /// `has_pending_typed_operations`, so leaving it undrained would spin this loop to its
    /// 30 s deadline exactly the way the terminal witness once did.
    ///
    /// 🧹️ The terminal witness lands in its OWN outbox (`typed_completion_outbox`), which
    /// `has_pending_typed_operations` counts — leaving it undrained spun this loop until
    /// its 30 s deadline for every operation that produced no lane page at all
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    ///
    /// 📜️ A pending history patch (a time-travel stage change) rides a UI-progress frame the host takes every turn;
    /// left untaken it kept `has_pending_typed_operations` true until the deadline for the first operation after a
    /// history edit (ticket 26/09/30/NON-DESTRUCTIVE-HISTORY-EDITING, forms frozen-press law).
    pub async fn settle_registered_typed_operation<P: PluginApp>(app: &mut P, receiver: u32) -> Result<TypedOperationFixtureReceipt, super::Fault> {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        let mut receipt = TypedOperationFixtureReceipt { lanes: Vec::new(), effects: Vec::new(), events: Vec::new(), ui_scope: None, completions: 0, completion_operations: Vec::new(), revisions: Vec::new(), composed: Vec::new() };
        let mut publication_fault = None;
        while app.has_pending_typed_operations() {
            if std::time::Instant::now() >= deadline {
                return Err(super::Fault::from("registered fixture typed operation did not retire within 30 seconds"));
            }
            if let super::PluginCloseStep::Pending { released_items, released_bytes } = app.maintenance_step(1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES)? {
                if released_items > 1 || released_bytes > store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES {
                    return Err(super::Fault::from(format!(
                        "registered fixture typed operation exceeded its exact maintenance grant: stage {} released {released_items} items / {released_bytes} bytes against a grant of 1 item / {} bytes",
                        crate::app::LAST_MAINTENANCE_STAGE.load(std::sync::atomic::Ordering::Relaxed),
                        store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES
                    )));
                }
            }
            app.advance_typed_operation_publication().await?;
            while let Some(page) = app.take_typed_operation_result_page(receiver) {
                let lane = page.lane;
                let fault = (lane == TypedOperationResultLane::Fault).then(|| crate::app::decode_typed_operation_fault_page(page.bytes()));
                if !app.acknowledge_typed_operation_result(page.token)? {
                    return Err(super::Fault::from("registered fixture typed operation rejected its exact result ACK"));
                }
                receipt.lanes.push(lane);
                publication_fault = publication_fault.or(fault);
            }
            while let Some(effect) = app.take_typed_operation_effect() {
                receipt.effects.push(effect);
            }
            while let Some(event) = app.take_typed_operation_event() {
                receipt.events.push(event);
            }
            while let Some(scope) = app.take_typed_operation_ui_scope() {
                receipt.ui_scope = Some(scope);
            }
            while let Some(progress) = app.take_typed_operation_ui_progress() {
                receipt.ui_scope = receipt.ui_scope.or(Some(progress.ui_scope));
            }
            while let Some(composed) = app.take_typed_operation_composed_result() {
                receipt.composed.push(composed);
            }
            while let Some(completion) = app.take_typed_operation_completion().await? {
                receipt.completions += 1;
                receipt.completion_operations.push(completion.operation);
                receipt.revisions.push(completion.revision);
            }
            while let Some(reply) = app.take_local_interaction_query_reply() {
                if let protocol::LocalInteractionQueryReply::Page { page } = reply {
                    let token = protocol::LocalInteractionQueryToken { request_id: page.request_id, query_generation: page.query_generation, identity: page.identity.clone(), ordinal: page.ordinal };
                    if !app.acknowledge_local_interaction_query(&token) {
                        return Err(super::Fault::from("registered fixture typed operation rejected its exact local-interaction ACK"));
                    }
                }
            }
            std::thread::yield_now();
        }
        publication_fault.map_or(Ok(receipt), Err)
    }

    /// 🔁️ One minted extension invocation as a fixture observes it — the `Effect::InvokeExtension`
    /// `reactor::poll` would have handed the shell.
    pub struct PendingExtensionInvocation {
        pub extension_id: String,
        pub capability: String,
        pub request_json: String,
    }

    /// 🔁️ The HOST half of the extension round trip, for a fixture that drives a `PluginApp`
    /// directly and therefore has no `reactor::poll` to carry it.
    ///
    /// An app declares its request through `Emit::extension_invocations`; the SDK mints the
    /// `req`, parks a continuation and queues one `Effect::InvokeExtension` on the actor's
    /// outbound queue. In production the shell runs the capability and answers with
    /// `Event::Completed`, which `poll` routes back into `plugin_dispatch_response_action`. This
    /// helper performs exactly those three steps: it drains the queued invocations, asks
    /// `serve` for each capability's bytes, and dispatches the recorded `response_action` — with
    /// the ORIGINAL request's own correlation fields plus `ok`/`outputJson` — back into `app`
    /// through the same `PluginApp::handle_command` seam, settling each redispatch. Returns how
    /// many invocations were answered, so a caller can loop until the chain quiesces
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    /// 🔁️ What one settled round of extension answers produced: how many invocations were
    /// answered, and every `Effect` the redispatched response actions emitted in turn — a
    /// continuation that re-arms its own chain (e.g. `flowEvalResolve` → `flowEvalTick`) is only
    /// observable to the caller through these (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    pub struct SettledExtensionInvocations {
        pub answered: usize,
        pub effects: Vec<semio_framework::kernel::Effect>,
    }

    /// 📦️ Exactly what `runCapturedExtensionEffect` (`🏛️ShellHost/🟦️.tsx`) does with the
    /// capability's own JSON answer before it crosses the ABI:
    /// `encodePackValue(JSON.parse(outputJson))`. A fixture that handed the raw JSON
    /// bytes over instead was green against a shape the shell never sends
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    pub async fn settle_extension_invocations<P: PluginApp>(
        app: &mut P,
        receiver: u32,
        action_meta: &ActionMeta,
        serve: &mut dyn FnMut(&PendingExtensionInvocation) -> Result<Vec<u8>, super::Fault>,
    ) -> Result<SettledExtensionInvocations, super::Fault> {
        use semio_framework::manifest::{CommandAddress, CommandInvocation, CommandOwnerAddress};
        let mut settled = SettledExtensionInvocations { answered: 0, effects: Vec::new() };
        for effect in crate::reactor::drain_queued_effects(receiver) {
            let semio_framework::kernel::Effect::InvokeExtension { req, extension_id, capability, request_json, .. } = effect else { continue };
            let pending = PendingExtensionInvocation { extension_id, capability, request_json };
            let outcome = serve(&pending).and_then(|json| {
                let text = String::from_utf8(json).map_err(|error| super::Fault::new(semio_framework::FaultOrigin::Plugin, semio_framework::FaultCode::new("extension.answer-not-json"), error.to_string()))?;
                let value = semio_framework_pack_json::from_json_str::<super::DslValue>(&text, semio_framework_pack_json::JsonMemberPolicy::Reject)
                    .map_err(|error| super::Fault::new(semio_framework::FaultOrigin::Plugin, semio_framework::FaultCode::new("extension.answer-not-json"), format!("the served capability answer is not JSON: {error}")))?;
                Ok(store::pack_rt::encode_wire_value(&value))
            });
            let Ok((instance, action, args)) = crate::reactor::take_extension_response(req, outcome) else { continue };
            let arguments = match args {
                super::DslValue::Object(entries) => entries.into_iter().collect(),
                _ => std::collections::BTreeMap::new(),
            };
            let app_id = app.app_id().await.to_string();
            let invocation = CommandInvocation { address: CommandAddress { owner: CommandOwnerAddress::App { plugin_id: String::new(), app_id }, command_id: action }, arguments };
            let meta = ActionMeta { instance_id: instance, ..action_meta.clone() };
            app.handle_command(&invocation, None, &meta).await?;
            settled.effects.extend(settle_registered_typed_operation(app, receiver).await?.effects);
            settled.answered += 1;
        }
        Ok(settled)
    }

    /// 🧹️ Closes one registered fixture through the exact retained app close state machine.
    pub fn close_registered_fixture_app<A: PluginApp>(app: &mut A) {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        let mut pending_authority = None;
        let mut close_turn = 0usize;
        while std::time::Instant::now() < deadline {
            if app.close_terminal_is_empty() {
                return;
            }
            match app.close_step(1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES).expect("registered fixture close") {
                super::PluginCloseStep::Pending { released_items, released_bytes } => {
                    assert!(
                        released_items <= 1 && released_bytes <= store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES,
                        "registered fixture close turn {close_turn} exceeded its exact grant: released {released_items} items / {released_bytes} bytes against 1 item / {} bytes",
                        store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES
                    );
                    if released_items == 0 && released_bytes == 0 {
                        std::thread::yield_now();
                    }
                }
                super::PluginCloseStep::AwaitingInput { reason } | super::PluginCloseStep::Blocked { reason } => {
                    pending_authority = Some(reason);
                    std::thread::yield_now();
                }
                super::PluginCloseStep::Complete => break,
            }
            close_turn = close_turn.saturating_add(1);
        }
        assert!(app.close_terminal_is_empty(), "registered fixture did not reach its exact terminal-empty witness{}", pending_authority.map(|reason| format!(", last pending close authority: {reason}")).unwrap_or_default());
    }

    /// 🔗️ Two registry-less store-only instances joined by an in-memory backbone on `channel`.
    pub async fn paired_apps<A: ArtifactApp + Default>(channel: &str) -> (VcsArtifactApp<A>, VcsArtifactApp<A>) {
        let mut a = new_app::<A>().await;
        let mut b = new_app::<A>().await;
        let (backbone_a, backbone_b) = MemoryBackbone::pair(channel, channel).await;
        a.attach_backbone(store::Backbones::Memory(backbone_a)).await.expect("attach a");
        b.attach_backbone(store::Backbones::Memory(backbone_b)).await.expect("attach b");
        (a, b)
    }

    /// 🧬️ Two explicitly registered fixture instances joined by an in-memory backbone, over the
    /// default (empty) member roster — the `NoMembers` spelling of
    /// [`paired_registered_apps_with_members`].
    pub async fn paired_registered_apps<A, Manifest, Build>(channel: &str, manifest: Build) -> (VcsArtifactApp<A>, VcsArtifactApp<A>)
    where
        A: ArtifactApp + Default,
        Manifest: std::future::Future<Output = App>,
        Build: Fn() -> Manifest,
    {
        paired_registered_apps_with_members::<A, super::NoMembers, Manifest, Build>(channel, manifest).await
    }

    /// 🧬️ [`paired_registered_apps`] over an explicit member roster `M` — see
    /// [`new_registered_app_with_members`] for why a composing app needs it.
    pub async fn paired_registered_apps_with_members<A, M, Manifest, Build>(channel: &str, manifest: Build) -> (VcsArtifactApp<A, M>, VcsArtifactApp<A, M>)
    where
        A: ArtifactApp + Default,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
        Manifest: std::future::Future<Output = App>,
        Build: Fn() -> Manifest,
    {
        let mut a = new_registered_app_with_members::<A, M, _>(manifest()).await;
        let mut b = new_registered_app_with_members::<A, M, _>(manifest()).await;
        a.bind_instance_id(meta("local").instance_id).await;
        b.bind_instance_id(meta("local").instance_id).await;
        let (backbone_a, backbone_b) = MemoryBackbone::pair(channel, channel).await;
        a.attach_backbone(store::Backbones::Memory(backbone_a)).await.expect("attach a");
        b.attach_backbone(store::Backbones::Memory(backbone_b)).await.expect("attach b");
        (a, b)
    }

    /// ⏪️ Drives ONE framework-reserved history verb the whole way a shell does: `handle_action`
    /// only ADMITS `"undo"`/`"redo"` — they are `framework_reserved_job!` routes
    /// (`FrameworkUndoJob`/`FrameworkRedoJob`), so the admission comes back as an
    /// `Effect::SpawnJob { kind: FRAMEWORK_RESERVED_JOB_KIND }` the caller has to run before the
    /// store ever sees `ArtifactCommand::Undo`. Dropping that receipt and pumping only the typed
    /// publication left every retained app's undo a no-op, which read as a flaky
    /// `undo did not revert to the expected snapshot` (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    /// A non-retained app admits no spawn job and
    /// [`super::settle_framework_reserved_admission`] hands the same result straight back.
    pub async fn settle_history_verb<A, M>(app: &mut VcsArtifactApp<A, M>, action: &str, receiver: u32)
    where
        A: ArtifactApp,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        let admitted = app.handle_action(action, None, &meta("local")).await.unwrap_or_else(|fault| panic!("history verb {action} admission: {fault:?}"));
        super::settle_framework_reserved_admission(app, admitted).await.unwrap_or_else(|fault| panic!("history verb {action} reserved-job commit: {fault:?}"));
        settle_registered_typed_operation(app, receiver).await.unwrap_or_else(|fault| panic!("history verb {action} publication: {fault:?}"));
    }

    /// 🧪️ Runs `command` once via the typed channel, asserts `probe(app)` matches `after`, undoes (still
    /// the framework-reserved `"undo"` action) and asserts `before`, redoes and asserts `after` again — the
    /// repeated undo/redo round-trip test body. B1: takes a typed `A::Command` value (`dispatch_typed`) —
    /// `ArtifactApp::handle_action`'s stringly-typed dispatch no longer exists.
    ///
    /// 🔁️ Every step SETTLES: a retained tool's `dispatch_typed` only returns an admission
    /// receipt, so probing straight after it observes the pre-command document and the
    /// round trip passes or fails against the wrong state entirely. A non-retained app has
    /// nothing pending and settles in zero turns (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    pub async fn assert_undo_redo_round_trip<A, M, P>(app: &mut VcsArtifactApp<A, M>, command: A::Command, probe: impl Fn(&VcsArtifactApp<A, M>) -> P, before: P, after: P)
    where
        A: ArtifactApp,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
        P: PartialEq + std::fmt::Debug,
    {
        let receiver = meta("local").instance_id;
        app.dispatch_typed(command, &meta("local")).await.expect("apply command");
        settle_registered_typed_operation(app, receiver).await.expect("apply command publication");
        assert_eq!(probe(app), after, "command did not produce the expected snapshot");
        settle_history_verb(app, "undo", receiver).await;
        assert_eq!(probe(app), before, "undo did not revert to the expected snapshot");
        settle_history_verb(app, "redo", receiver).await;
        assert_eq!(probe(app), after, "redo did not reapply the expected snapshot");
    }

    /// 🧬️ Preserves declared defaults and stages schema-validated representatives for required bridge inputs.
    fn declared_bridge_arguments(args: &[semio_framework::ActionArgDef]) -> Result<semio_framework::DslValue, String> {
        use semio_framework::{ArgSchema, DslValue};
        let mut representatives = Vec::new();
        for argument in args.iter().filter(|argument| argument.required && argument.default.is_none()) {
            let candidates = match &argument.schema {
                ArgSchema::String { options, .. } if options.len() == 1 => vec![DslValue::String(options[0].value.clone())],
                _ => declared_argument_alternatives(argument).map(|(first, second)| vec![first, second]).unwrap_or_default(),
            };
            let schema = argument.json_schema(semio_framework_ui_locale::Terminology::Native, semio_framework_ui_locale::Locale::En);
            let validator = semio_framework_schema::OwnedJsonSchemaValidator::compile(&semio_framework_pack_json::to_json_string(&schema)).map_err(|error| format!("required argument {} schema cannot be validated: {error}", argument.id))?;
            let value = candidates
                .into_iter()
                .find(|candidate| validator.validate_json(&semio_framework_pack_json::to_json_string(candidate)).is_ok())
                .ok_or_else(|| format!("required argument {} has no supported schema-valid representative: {:?}", argument.id, argument.schema))?;
            representatives.push((argument.id.clone(), value));
        }
        Ok(semio_framework::effective_action_args(args, &DslValue::Object(representatives), None))
    }

    /// 🧪️ Every declared app action bridges through `command_from_action` and round-trips `command_id`
    /// with its declared defaults and schema-validated representatives for required inputs without defaults.
    ///
    /// 🧱️ Window-KIT catalog rows are framework-owned surface verbs, not app actions: the shared
    /// `window_kind_definition` scaffold below mints them (and stamps them `Migrated`) for the
    /// editable variants of `TextWindowKit`/`TableWindowKit`/`TreeWindowKit`, so every app that
    /// composes one of those kits inherits an id it never authored a command row for. They belong
    /// in this skip list for exactly the same reason the framework-reserved verbs above do.
    pub async fn assert_declared_actions_bridge_to_commands<A: ArtifactApp + Default>(manifest: fn() -> App) {
        let definition = manifest().definition;
        let _app = A::default();
        let skip = [
            "undo",
            "redo",
            "commitCheckpoint",
            "createAlternative",
            "switchAlternative",
            "checkoutCheckpoint",
            "copy",
            "cut",
            "paste",
            "revertToCommand",
            "setHistoryCommandFilter",
            "noteShellCommand",
            "recordTutorial",
            "startIntroduction",
            "startTutorial",
            "setActiveUtility",
            "setActiveTool",
            semio_framework::EXPORT_ARTIFACT_DOCUMENT_ACTION_ID,
            semio_framework::IMPORT_ARTIFACT_DOCUMENT_ACTION_ID,
            "interactionSelect",
            "interactionHover",
            "clearSelection",
            "selectAll",
            "setSelectionMode",
            "setInteractionGranularity",
        ];
        for action in definition.window_kinds.iter().flat_map(|window| semio_framework::window_kind_actions(&definition, window)) {
            if skip.contains(&action.id.as_str())
                || crate::is_tool_run_action_id(&action.id)
                || crate::is_time_travel_action_id(&action.id)
                || action.id == crate::plugin_app_close_prelude::CANCEL_TYPED_OPERATION_ACTION_ID
                || action.id == semio_framework::HOST_EVENT_ACTION_ID
            {
                continue;
            }
            if action.id == crate::app::TextWindowKit::EDIT_ACTION_ID || matches!(action.id.as_str(), "set-cell" | "set-node") {
                continue;
            }
            let staged = declared_bridge_arguments(&action.args).unwrap_or_else(|error| panic!("action {} could not stage required arguments: {error}", action.id));
            let command = A::command_from_action(&action.id, Some(&staged)).await.unwrap_or_else(|error| panic!("action {} failed to bridge: {}", action.id, error.message));
            assert_eq!(A::command_id(&command).await, action.id.as_str(), "command_id mismatch for action {}", action.id);
        }
    }

    //#region 🔖️DeclaredVerbLaws
    /// 🎯️ What one dispatch of a declared verb did, observed exactly where the shell observes it: the
    /// host action entry (`PluginApp::handle_action`), the retained publication settle, and the state
    /// read back afterwards. The declaration (`ActionKind`, audience, `effects.destructive`, args) is
    /// what users, collaborators and agents rely on; these laws hold the handler to it
    /// (ticket 26/09/23/END-TO-END-OS-HUB-COLLABORATION-MCP, slice P8).
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub enum DeclaredVerbOutcome {
        /// 🚪️ The dispatch infrastructure refused the verb before any handler ran (`interactive-job.*`,
        /// `app.command.unsupported`) — the declared verb cannot be invoked at all.
        Unreachable { code: String, detail: String },
        /// 🛑️ The handler refused this invocation by name.
        Refused { code: String, detail: String },
        /// ✅️ The operation settled; see [`DeclaredVerbEffect`].
        Settled(DeclaredVerbEffect),
    }

    /// 📤️ The observable effect of one settled dispatch — published lanes, requested host effects and
    /// the document/config change read back from the stores.
    #[derive(Clone, Debug, Default, PartialEq, Eq)]
    pub struct DeclaredVerbEffect {
        pub lanes: std::collections::BTreeSet<&'static str>,
        pub document_changed: bool,
        pub document_replaced: bool,
        pub config_changed: bool,
        pub user_path_written: bool,
        pub host_effects: usize,
        pub fingerprint: u64,
        /// 🪆️ `slot/child_id` of every composed child the parent names after the verb and no store holds,
        /// that it did not already name unheld before the verb.
        pub orphaned_children: Vec<String>,
    }

    impl DeclaredVerbEffect {
        /// 🔇️ Nothing observable happened: no store lane beyond the terminal/UI witnesses, no host
        /// effect or event, no document or config change.
        pub fn is_silent(&self) -> bool {
            !self.touches_document() && !self.config_changed && !self.user_path_written && self.host_effects == 0 && self.lanes.iter().all(|lane| matches!(*lane, "terminal" | "ui"))
        }

        /// 📝️ Wrote the document (its own ops or an owned child's) or asked the host to replace it.
        pub fn touches_document(&self) -> bool {
            self.document_changed || self.document_replaced || self.lanes.contains("artifact") || self.lanes.contains("child")
        }
    }

    /// 🧪️ One declared verb probed on its app's own boot fixture, from every window kind that presents
    /// it (a window-claimed verb from its own window, an app-level verb from each window a shell can
    /// dispatch it from — a window-config verb only acts from its own window).
    #[derive(Clone, Debug, PartialEq)]
    pub struct DeclaredVerbProbe {
        pub verb: String,
        pub kind: semio_framework::ActionKind,
        pub audience: semio_framework::CapabilityAudience,
        pub destructive: bool,
        pub bridge: Result<(), String>,
        pub windows: Vec<DeclaredVerbWindowProbe>,
        /// 🤖️ The same staged invocation through the agent lane (`dispatch_command_frame`, the MCP
        /// `action_prepare` phase) at the address the capability catalog publishes; `None` for a
        /// verb agents never see (Input/Chrome audience).
        pub agent: Option<DeclaredVerbOutcome>,
    }

    /// 🪟️ The verb dispatched from one window kind: once with the staged declared defaults, then twice
    /// per perturbable declared argument with two distinct valid values.
    #[derive(Clone, Debug, PartialEq)]
    pub struct DeclaredVerbWindowProbe {
        pub window: String,
        pub staged: DeclaredVerbOutcome,
        pub arguments: Vec<DeclaredArgumentProbe>,
    }

    /// 🔀️ The same verb dispatched with two distinct values of one declared argument. `others_specified`
    /// says every OTHER declared argument carried a value (a declared default or the surface's example),
    /// so a refusal cannot be blamed on a missing sibling.
    #[derive(Clone, Debug, PartialEq)]
    pub struct DeclaredArgumentProbe {
        pub argument: String,
        pub others_specified: bool,
        pub first: DeclaredVerbOutcome,
        pub second: DeclaredVerbOutcome,
    }

    /// ⚖️ One way a handler breaks its verb's declaration.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub enum DeclaredVerbFinding {
        /// 📝️ A `View`/`🐚️Shell` verb wrote or replaced the document (law a).
        DocumentWriteFromNonMutation { verb: String, kind: String },
        /// 🔇️ An agent-facing `Mutation` verb settled without any observable effect for every probe (law b).
        SilentMutation { verb: String },
        /// 🔀️ Two distinct values of one declared argument produced the identical outcome (law c).
        IgnoredArgument { verb: String, argument: String },
        /// ⚠️ A verb declared destructive settled without writing the document or a user file.
        DestructiveWithoutDiscard { verb: String },
        /// 🚪️ The dispatch infrastructure refused the declared verb before its handler ran.
        Unreachable { verb: String, code: String },
        /// 🌉️ The declared verb does not bridge to a command with its staged declared defaults.
        Unbridged { verb: String, detail: String },
        /// 🤖️ An agent invoking the verb gets a different effect than a human pressing it: refused or
        /// silent where the shell acts, or writing the document where the shell does not (and vice versa).
        AgentLaneDiverges { verb: String, shell: String, agent: String },
        /// 🪆️ The verb left the parent naming a composed child no store holds — every later verb, window and
        /// reload that reads the child finds nothing (flow's parent-lane edits re-minted its content child).
        ComposedChildOrphaned { verb: String, children: String },
    }

    impl std::fmt::Display for DeclaredVerbFinding {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            match self {
                DeclaredVerbFinding::DocumentWriteFromNonMutation { verb, kind } => write!(formatter, "{verb}: declared {kind} but wrote or replaced the document"),
                DeclaredVerbFinding::SilentMutation { verb } => write!(formatter, "{verb}: declared Mutation but every probe settled silently — refuse by name or act"),
                DeclaredVerbFinding::IgnoredArgument { verb, argument } => write!(formatter, "{verb}: two distinct values of declared argument `{argument}` produced the identical outcome"),
                DeclaredVerbFinding::DestructiveWithoutDiscard { verb } => write!(formatter, "{verb}: declared destructive but settled without writing the document or a user file"),
                DeclaredVerbFinding::Unreachable { verb, code } => write!(formatter, "{verb}: the dispatch infrastructure refused it before its handler ran ({code})"),
                DeclaredVerbFinding::Unbridged { verb, detail } => write!(formatter, "{verb}: does not bridge with its staged declared defaults ({detail})"),
                DeclaredVerbFinding::AgentLaneDiverges { verb, shell, agent } => write!(formatter, "{verb}: the agent lane diverges from the shell lane (shell {shell}; agent {agent})"),
                DeclaredVerbFinding::ComposedChildOrphaned { verb, children } => write!(formatter, "{verb}: leaves the parent naming composed children no store holds ({children})"),
            }
        }
    }

    /// ⚖️ The declared-verb verdict — a pure function of one probe, stated once for every plugin and
    /// held against the language-agnostic fixture `🧫️fixtures/⚖️declared-verb-verdicts.json`.
    /// (a) no `View`/`🐚️Shell` verb touches the document from any window; (b) an agent-facing
    /// `Mutation` verb never settles silently on every probe of every window; (c) no agent- or
    /// chrome-facing verb ignores a declared argument in every window that probed it; a destructive
    /// verb discards something whenever it settles; every declared agent or chrome verb bridges with
    /// its staged declared defaults (an Input gesture's payload is the host's) and every declared verb
    /// is reachable from at least one window; an agent-facing verb's agent lane writes the document
    /// exactly when the shell lane does and acts wherever the shell acts (never refused or silent there).
    pub fn declared_verb_findings(probe: &DeclaredVerbProbe) -> Vec<DeclaredVerbFinding> {
        use semio_framework::{ActionKind, CapabilityAudience};
        let verb = probe.verb.clone();
        if let Err(detail) = &probe.bridge {
            return match probe.audience {
                CapabilityAudience::Input => Vec::new(),
                _ => vec![DeclaredVerbFinding::Unbridged { verb, detail: detail.clone() }],
            };
        }
        if let Some(DeclaredVerbOutcome::Unreachable { code, .. }) =
            probe.windows.iter().map(|window| &window.staged).find(|staged| matches!(staged, DeclaredVerbOutcome::Unreachable { .. })).filter(|_| probe.windows.iter().all(|window| matches!(window.staged, DeclaredVerbOutcome::Unreachable { .. })))
        {
            return vec![DeclaredVerbFinding::Unreachable { verb, code: code.clone() }];
        }
        let outcomes = || probe.windows.iter().flat_map(|window| std::iter::once(&window.staged).chain(window.arguments.iter().flat_map(|argument| [&argument.first, &argument.second])));
        let settled = || outcomes().filter_map(|outcome| if let DeclaredVerbOutcome::Settled(effect) = outcome { Some(effect) } else { None });
        let mut findings = Vec::new();
        if !matches!(probe.kind, ActionKind::Mutation) && settled().any(DeclaredVerbEffect::touches_document) {
            findings.push(DeclaredVerbFinding::DocumentWriteFromNonMutation { verb: verb.clone(), kind: format!("{:?}", probe.kind) });
        }
        if matches!(probe.kind, ActionKind::Mutation) && probe.audience == CapabilityAudience::Agent && outcomes().all(|outcome| matches!(outcome, DeclaredVerbOutcome::Settled(effect) if effect.is_silent())) {
            findings.push(DeclaredVerbFinding::SilentMutation { verb: verb.clone() });
        }
        if probe.destructive && settled().next().is_some() && settled().all(|effect| !effect.touches_document() && !effect.user_path_written) {
            findings.push(DeclaredVerbFinding::DestructiveWithoutDiscard { verb: verb.clone() });
        }
        if let Some(effect) = settled().find(|effect| !effect.orphaned_children.is_empty()) {
            findings.push(DeclaredVerbFinding::ComposedChildOrphaned { verb: verb.clone(), children: effect.orphaned_children.join(", ") });
        }
        if let Some(agent) = &probe.agent {
            let shell_writes = probe.windows.iter().any(|window| declared_verb_wrote_document(&window.staged));
            let shell_acts = probe.windows.iter().any(|window| matches!(&window.staged, DeclaredVerbOutcome::Settled(effect) if !effect.is_silent()));
            let agent_writes = declared_verb_wrote_document(agent);
            let agent_acts = matches!(agent, DeclaredVerbOutcome::Settled(effect) if !effect.is_silent());
            if shell_writes != agent_writes || (shell_acts && !agent_acts) {
                let describe = |outcome: &DeclaredVerbOutcome| match outcome {
                    DeclaredVerbOutcome::Unreachable { code, .. } => format!("unreachable {code}"),
                    DeclaredVerbOutcome::Refused { code, .. } => format!("refused {code}"),
                    DeclaredVerbOutcome::Settled(effect) if effect.touches_document() => "writes the document".to_string(),
                    DeclaredVerbOutcome::Settled(effect) if effect.is_silent() => "changes nothing".to_string(),
                    DeclaredVerbOutcome::Settled(_) => "acts without writing the document".to_string(),
                };
                let shell = probe.windows.iter().map(|window| format!("{}: {}", window.window, describe(&window.staged))).collect::<Vec<_>>().join(", ");
                findings.push(DeclaredVerbFinding::AgentLaneDiverges { verb: verb.clone(), shell, agent: describe(agent) });
            }
        }
        if probe.audience != CapabilityAudience::Input {
            let mut names: Vec<&str> = Vec::new();
            for argument in probe.windows.iter().flat_map(|window| window.arguments.iter()) {
                if !names.contains(&argument.argument.as_str()) {
                    names.push(argument.argument.as_str());
                }
            }
            for name in names {
                let mut probes = probe.windows.iter().flat_map(|window| window.arguments.iter().map(move |argument| (&window.staged, argument))).filter(|(_, argument)| argument.argument == name).peekable();
                if probes.peek().is_some() && probes.all(|(staged, argument)| declared_verb_outcomes_agree(staged, &argument.first, &argument.second, argument.others_specified)) {
                    findings.push(DeclaredVerbFinding::IgnoredArgument { verb: verb.clone(), argument: name.to_string() });
                }
            }
        }
        findings
    }

    /// 🟰️ Two outcomes an observer cannot tell apart. Two equal settles always agree. Two infrastructure
    /// refusals prove nothing about the argument. Two equal handler refusals agree only when every
    /// sibling argument carried a value (otherwise the missing sibling may be what was refused) and the
    /// staged invocation, which leaves this argument at its default, was refused identically too — a
    /// body both perturbations fail to parse the same way was still read, since its default did not.
    fn declared_verb_outcomes_agree(staged: &DeclaredVerbOutcome, first: &DeclaredVerbOutcome, second: &DeclaredVerbOutcome, others_specified: bool) -> bool {
        match (first, second) {
            (DeclaredVerbOutcome::Settled(first), DeclaredVerbOutcome::Settled(second)) => first == second,
            (DeclaredVerbOutcome::Refused { .. }, DeclaredVerbOutcome::Refused { .. }) => others_specified && first == second && staged == first,
            _ => false,
        }
    }

    /// 🔀️ Two distinct valid values for one declared argument, or `None` when its schema admits no
    /// generic pair (a single-option choice, a record, a host-resolved choice, `Any`).
    fn declared_argument_alternatives(argument: &semio_framework::ActionArgDef) -> Option<(semio_framework::DslValue, semio_framework::DslValue)> {
        use semio_framework::{ArgFormat, ArgSchema, DslValue};
        let text = |value: &str| DslValue::String(value.to_string());
        match &argument.schema {
            ArgSchema::String { options, .. } if options.len() >= 2 => Some((text(&options[0].value), text(&options[1].value))),
            ArgSchema::String { options, .. } if !options.is_empty() => None,
            ArgSchema::String { format: Some(ArgFormat::ArtifactKind { .. } | ArgFormat::SurfaceApp { .. }), .. } => None,
            ArgSchema::String { format: Some(ArgFormat::Json), .. } => Some((text("{}"), text("[]"))),
            ArgSchema::String { .. } => Some((text("p8-alpha"), text("p8-beta"))),
            ArgSchema::Number { min, max, integer, .. } => {
                let (low, high) = match (min, max) {
                    (Some(low), Some(high)) if high > low => (*low, *high),
                    (Some(low), _) => (*low, *low + 1.0),
                    (None, Some(high)) => (*high - 1.0, *high),
                    (None, None) => (1.0, 2.0),
                };
                let number = |value: f64| {
                    if *integer && value >= 0.0 {
                        DslValue::uint(value as u64)
                    } else if *integer {
                        DslValue::int(value as i64)
                    } else {
                        DslValue::float(value)
                    }
                };
                Some((number(low), number(high)))
            }
            ArgSchema::Boolean => Some((DslValue::Bool(false), DslValue::Bool(true))),
            ArgSchema::Vector { dims, .. } => {
                let vector = |start: f64, direction: f64| DslValue::Array((0..*dims).map(|index| DslValue::float(start + direction * f64::from(index))).collect());
                Some((vector(1.0, 1.0), vector(f64::from(*dims), -1.0)))
            }
            ArgSchema::Reference { many: false, .. } => Some((text("p8-alpha"), text("p8-beta"))),
            ArgSchema::Reference { many: true, .. } => Some((DslValue::Array(vec![text("p8-alpha")]), DslValue::Array(vec![text("p8-beta")]))),
            ArgSchema::Array { items, .. } => match items.as_ref() {
                ArgSchema::String { options, .. } if options.len() >= 2 => Some((DslValue::Array(vec![text(&options[0].value)]), DslValue::Array(vec![text(&options[1].value)]))),
                ArgSchema::String { options, .. } if options.is_empty() => Some((DslValue::Array(vec![text("p8-alpha")]), DslValue::Array(vec![text("p8-beta")]))),
                ArgSchema::Number { .. } => Some((DslValue::Array(vec![DslValue::uint(1)]), DslValue::Array(vec![DslValue::uint(2)]))),
                _ => None,
            },
            ArgSchema::String { .. } | ArgSchema::Object { .. } | ArgSchema::Any => None,
        }
    }

    /// 🏷️ The stable lower-case name of one published result lane.
    fn declared_verb_lane_name(lane: TypedOperationResultLane) -> &'static str {
        match lane {
            TypedOperationResultLane::Artifact => "artifact",
            TypedOperationResultLane::Config => "config",
            TypedOperationResultLane::Draft => "draft",
            TypedOperationResultLane::Presence => "presence",
            TypedOperationResultLane::Transient => "transient",
            TypedOperationResultLane::WindowConfig => "windowConfig",
            TypedOperationResultLane::WindowTransient => "windowTransient",
            TypedOperationResultLane::Child => "child",
            TypedOperationResultLane::Interaction => "interaction",
            TypedOperationResultLane::Effect => "effect",
            TypedOperationResultLane::Event => "event",
            TypedOperationResultLane::Ui => "ui",
            TypedOperationResultLane::Download => "download",
            TypedOperationResultLane::Terminal => "terminal",
            TypedOperationResultLane::Fault => "fault",
        }
    }

    /// #️⃣ FNV-1a over every observed part of one settled dispatch.
    fn declared_verb_fingerprint<'a>(parts: impl IntoIterator<Item = &'a [u8]>) -> u64 {
        let mut hash = 0xcbf2_9ce4_8422_2325_u64;
        for part in parts {
            for byte in part.iter().chain(&[0xff]) {
                hash ^= u64::from(*byte);
                hash = hash.wrapping_mul(0x0100_0000_01b3);
            }
        }
        hash
    }

    /// 🚪️ Infrastructure refusals (the verb never reached its handler) versus a handler's own refusal.
    /// `interactive-job.app-owned-output` is the code a retained job's fault page carries when the
    /// handler's own `Fault` crossed the publication boundary, so it is the handler's refusal.
    fn declared_verb_refusal(fault: super::Fault) -> DeclaredVerbOutcome {
        let code = fault.code.0.clone();
        if (code.starts_with("interactive-job.") && code != "interactive-job.app-owned-output") || code == "app.command.unsupported" {
            DeclaredVerbOutcome::Unreachable { code, detail: fault.message }
        } else {
            DeclaredVerbOutcome::Refused { code, detail: fault.message }
        }
    }

    /// 🎬️ How a fresh probe fixture boots the app's own example: its `setActiveExample` invocation (the
    /// staged declared defaults overlaid by the surface's example arguments) from the window that
    /// presents it — replayed on every fixture, so an example that lands as operations, as owned
    /// children or as a host `LoadDocument` boots the same way the shell boots it.
    pub struct DeclaredVerbBoot {
        args: semio_framework::DslValue,
        view: super::ViewModel,
    }

    /// 🎬️ The arguments the shell's example picker boots with: the staged declared defaults, and for every
    /// closed choice still without a value its first option — the example the navbar opens first.
    fn declared_verb_boot_args(action: &semio_framework::ActionDefinition, staged: semio_framework::DslValue) -> semio_framework::DslValue {
        use semio_framework::{ArgSchema, DslValue};
        let DslValue::Object(mut entries) = staged else { return staged };
        for argument in &action.args {
            let ArgSchema::String { options, .. } = &argument.schema else { continue };
            let Some(first) = options.first() else { continue };
            if !entries.iter().any(|(key, value)| key == &argument.id && !matches!(value, DslValue::Null) && value.as_str() != Some("")) {
                entries.retain(|(key, _)| key != &argument.id);
                entries.push((argument.id.clone(), DslValue::String(first.value.clone())));
            }
        }
        DslValue::Object(entries)
    }

    /// 🧫️ The per-probe fixture: the registered app, bound as instance 1, booted with the app's own
    /// example when it declares one.
    async fn declared_verb_fixture_app<A, M>(definition: &semio_framework::AppDefinition, boot: Option<&DeclaredVerbBoot>) -> VcsArtifactApp<A, M>
    where
        A: ArtifactApp + Default,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        let mut app = VcsArtifactApp::<A, M>::with_registry(A::default(), AppActionRegistry::from_definition(definition)).await;
        app.bind_instance_id(meta("local").instance_id).await;
        if let Some(boot) = boot {
            let action_meta = ActionMeta { view_state: Some(boot.view.clone()), ..meta("local") };
            let result = app.handle_action("setActiveExample", Some(&boot.args), &action_meta).await.unwrap_or_else(|fault| panic!("the app's own boot example must be admitted: {fault:?}"));
            let receipt = settle_registered_typed_operation(&mut app, action_meta.instance_id).await.unwrap_or_else(|fault| panic!("the app's own boot example must settle: {fault:?}"));
            for effect in result.requested_effects.into_iter().chain(receipt.effects) {
                if let semio_framework::kernel::Effect::LoadDocument { pack, spr } = effect {
                    load_document(&mut app, &store::ArtifactPackFiles { pack, spr, ops: String::new() }).await.unwrap_or_else(|fault| panic!("the app's own boot example must load: {fault:?}"));
                }
            }
            app.follow_derivable_children().await.unwrap_or_else(|fault| panic!("the boot example's derivable children must follow its coordinates: {fault:?}"));
        }
        app
    }

    /// 📦️ The document (with every owned child's envelope) and config packs the stores hold right now.
    async fn declared_verb_state<A, M>(app: &mut VcsArtifactApp<A, M>) -> (Vec<u8>, Vec<u8>)
    where
        A: ArtifactApp,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        let mut document = app.snapshot().map(|snapshot| store::ArtifactPack::encode_pack(&snapshot)).unwrap_or_default();
        for child in PluginApp::child_packs(app).await.unwrap_or_default() {
            document.extend_from_slice(child.slot.as_bytes());
            document.extend_from_slice(child.child_id.as_bytes());
            document.extend_from_slice(&child.envelope_pack);
        }
        let config = match app.refresh_cache().await {
            Ok(()) => app.cache.as_ref().map(|(_, _, config, _)| store::ArtifactPack::encode_pack(config.as_ref())).unwrap_or_default(),
            Err(_) => Vec::new(),
        };
        (document, config)
    }

    /// 🪆️ `slot/child_id` of every composed child the parent names right now that no child store holds.
    async fn declared_verb_unheld_children<A, M>(app: &VcsArtifactApp<A, M>) -> Vec<String>
    where
        A: ArtifactApp,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        let Ok(snapshot) = app.snapshot() else { return Vec::new() };
        let declared: Vec<(String, String)> = match store::ChildRestoreProjection::from_snapshot(&snapshot) {
            Ok(projection) => (0..projection.len()).filter_map(|index| projection.get(index)).map(|(slot, fields)| (slot.to_string(), fields.child_id.to_string())).collect(),
            Err(error) => vec![(String::from("projection"), error.to_string())],
        };
        let mut unheld = Vec::new();
        for (slot, child_id) in declared {
            if app.child_store(&slot, &child_id).await.is_none() {
                unheld.push(format!("{slot}/{child_id}"));
            }
        }
        unheld
    }

    /// 🎯️ Dispatches one declared verb exactly as the shell does and reads back what it did.
    async fn declared_verb_dispatch<A, M>(definition: &semio_framework::AppDefinition, boot: Option<&DeclaredVerbBoot>, verb: &str, args: &semio_framework::DslValue, view: &super::ViewModel, body_key: &str) -> DeclaredVerbOutcome
    where
        A: ArtifactApp + Default,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        let mut app = declared_verb_fixture_app::<A, M>(definition, boot).await;
        let (document_before, config_before) = declared_verb_state(&mut app).await;
        let unheld_before = declared_verb_unheld_children(&app).await;
        let action_meta = ActionMeta { view_state: Some(view.clone()), ..meta("local") };
        let receiver = action_meta.instance_id;
        let outcome = match app.handle_action(verb, Some(args), &action_meta).await {
            Err(fault) => declared_verb_refusal(fault),
            Ok(result) => match settle_registered_typed_operation(&mut app, receiver).await {
                Err(fault) => declared_verb_refusal(fault),
                Ok(receipt) => {
                    let effects = result.requested_effects.iter().chain(receipt.effects.iter()).map(|effect| format!("{effect:?}")).collect::<Vec<_>>();
                    let events = result.events.iter().chain(receipt.events.iter()).map(|event| format!("{event:?}")).collect::<Vec<_>>();
                    let replaced = result.requested_effects.iter().chain(receipt.effects.iter()).any(|effect| matches!(effect, semio_framework::kernel::Effect::LoadDocument { .. }));
                    let downloaded = result
                        .requested_effects
                        .iter()
                        .chain(receipt.effects.iter())
                        .any(|effect| matches!(effect, semio_framework::kernel::Effect::DownloadMediaExport { .. } | semio_framework::kernel::Effect::IconRenderExport { .. } | semio_framework::kernel::Effect::VideoRenderExport { .. }));
                    let lanes = receipt.lanes.iter().map(|lane| declared_verb_lane_name(*lane)).collect::<std::collections::BTreeSet<_>>();
                    let (document_after, config_after) = declared_verb_state(&mut app).await;
                    let orphaned_children = declared_verb_unheld_children(&app).await.into_iter().filter(|child| !unheld_before.contains(child)).collect();
                    let rendered = match app.render(body_key, None, view).await {
                        Ok(tree) => project_and_retire_fixture_tree(tree).unwrap_or_else(|error| format!("projection:{error}")),
                        Err(fault) => format!("render:{}", fault.code.0),
                    };
                    let lane_text = lanes.iter().copied().collect::<Vec<_>>().join(",");
                    let fingerprint = declared_verb_fingerprint(
                        [document_after.as_slice(), config_after.as_slice(), lane_text.as_bytes(), rendered.as_bytes()].into_iter().chain(effects.iter().map(|effect| effect.as_bytes())).chain(events.iter().map(|event| event.as_bytes())),
                    );
                    DeclaredVerbOutcome::Settled(DeclaredVerbEffect {
                        user_path_written: downloaded || lanes.contains("download"),
                        lanes,
                        document_changed: document_after != document_before,
                        document_replaced: replaced,
                        config_changed: config_after != config_before,
                        host_effects: effects.len() + events.len(),
                        fingerprint,
                        orphaned_children,
                    })
                }
            },
        };
        close_registered_fixture_app(&mut app);
        outcome
    }

    /// 🤖️ Previews `verb` with `args` exactly as the MCP gateway's `action_prepare` does — the agent lane's typed command
    /// frame, addressed to the caller's declared window instance with explicit language and terminology — and answers how many document ops
    /// the preview would commit (ticket 26/09/23, G12 session 14c).
    pub async fn agent_preview<A, M>(app: &mut VcsArtifactApp<A, M>, definition: &semio_framework::AppDefinition, verb: &str, args: &semio_framework::DslValue, view: &super::ViewModel) -> Result<usize, super::Fault>
    where
        A: ArtifactApp + Default,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        let window_kind_id = definition.window_kinds.iter().find(|window| semio_framework::window_kind_actions(definition, window).iter().any(|action| action.id == verb)).map_or_else(|| "*".to_string(), |window| window.id.clone());
        let window_instance_id = view.window_instances.iter().find(|window| window.window_kind_id == window_kind_id).ok_or_else(|| super::Fault::new(super::FaultOrigin::Plugin, super::FaultCode::new("fixture.agent-window"), "agent fixture requires its caller's declared window instance"))?.id.clone();
        let arguments = match args {
            semio_framework::DslValue::Object(entries) => entries.iter().cloned().collect(),
            _ => std::collections::BTreeMap::new(),
        };
        let invocation = super::ManifestActionInvocation {
            address: semio_framework::manifest::ActionAddress {
                plugin_id: String::new(),
                app_id: app.app.instance_id().await.to_string(),
                mode_id: definition.default_mode_id.clone(),
                window_kind_id,
                window_instance_id,
                action_id: verb.to_string(),
            },
            arguments,
        };
        let action_meta = ActionMeta { view_state: Some(view.clone()), ..meta("agent") };
        let result = app.preview_addressed_action(&invocation, &action_meta).await?;
        Ok(result.output.get("documentOps").and_then(|value| value.as_str()).and_then(|value| value.parse::<usize>().ok()).unwrap_or(0))
    }

    /// 🤖️ Dispatches one declared verb exactly as an agent does — the owner-qualified invocation the
    /// MCP gateway sends as a typed command frame (`dispatch_command_frame`, its `action_prepare`
    /// phase) — and reads back what that phase reports it would do.
    async fn declared_verb_agent_dispatch<A, M>(definition: &semio_framework::AppDefinition, boot: Option<&DeclaredVerbBoot>, verb: &str, args: &semio_framework::DslValue, window_kind_id: &str) -> DeclaredVerbOutcome
    where
        A: ArtifactApp + Default,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        let mut app = declared_verb_fixture_app::<A, M>(definition, boot).await;
        let app_id = app.app.instance_id().await.to_string();
        let arguments = match args {
            semio_framework::DslValue::Object(entries) => entries.iter().cloned().collect(),
            _ => std::collections::BTreeMap::new(),
        };
        let invocation = super::ManifestActionInvocation {
            address: semio_framework::manifest::ActionAddress {
                plugin_id: String::new(),
                app_id,
                mode_id: definition.default_mode_id.clone(),
                window_kind_id: window_kind_id.to_string(),
                window_instance_id: "declared-verb-agent".to_string(),
                action_id: verb.to_string(),
            },
            arguments,
        };
        let outcome = match app.preview_addressed_action(&invocation, &meta("agent")).await {
            Err(fault) => declared_verb_refusal(fault),
            Ok(result) => {
                let count = |key: &str| result.output.get(key).and_then(|value| value.as_str()).and_then(|value| value.parse::<usize>().ok()).unwrap_or(0);
                let (document, config, draft, children) = (count("documentOps"), count("configOps"), count("draftOps"), count("childGroups"));
                let lanes = [("artifact", document), ("config", config), ("draft", draft), ("child", children)].into_iter().filter(|(_, ops)| *ops != 0).map(|(lane, _)| lane).collect::<std::collections::BTreeSet<_>>();
                let host_effects = result.requested_effects.len() + result.events.len();
                let fingerprint = declared_verb_fingerprint([format!("{:?}", result.output).as_bytes()]);
                DeclaredVerbOutcome::Settled(DeclaredVerbEffect { lanes, document_changed: document != 0, document_replaced: false, config_changed: config != 0, user_path_written: false, host_effects, fingerprint, orphaned_children: Vec::new() })
            }
        };
        close_registered_fixture_app(&mut app);
        outcome
    }

    /// 🧪️ Probes every verb `definition` declares, on the app's own boot example: each window kind's
    /// resolved actions (framework-reserved, tool-run and host-owned utility/tool verbs excluded) are
    /// dispatched from an instance of that window kind with the staged declared defaults — overlaid by
    /// the surface's example arguments, `examples` = `{"verbs": {"<verb>": {"<arg>": <value>}}}`, the
    /// language-agnostic `🧫️fixtures/⚖️declared-verb-examples.json` of a surface whose verbs need
    /// document ids to act — then with two distinct values per perturbable declared argument. Every
    /// probe runs on a fresh registered app.
    pub async fn probe_declared_verbs<A, M>(definition: fn() -> semio_framework::AppDefinition, examples: Option<&str>) -> Vec<DeclaredVerbProbe>
    where
        A: ArtifactApp + Default,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        probe_declared_verbs_where::<A, M>(definition, examples, None).await
    }

    /// 🤖️ The agent lane beside the shell lane for exactly the named `verbs`, on the app's own boot example: each is
    /// dispatched with its staged declared defaults (overlaid by `examples`) from every window kind that presents it,
    /// and once through the agent lane at the address the capability catalog publishes — without argument
    /// perturbation, so a surface whose boot is expensive pins what an agent gets for the verbs it names.
    /// [`declared_verb_agent_divergences`] over the answer lists the named verbs whose two lanes disagree.
    pub async fn probe_agent_lane<A, M>(definition: fn() -> semio_framework::AppDefinition, examples: Option<&str>, verbs: &[&str]) -> Vec<DeclaredVerbProbe>
    where
        A: ArtifactApp + Default,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        let probes = probe_declared_verbs_where::<A, M>(definition, examples, Some(verbs)).await;
        let missing = verbs.iter().filter(|verb| !probes.iter().any(|probe| probe.verb == **verb)).collect::<Vec<_>>();
        assert!(missing.is_empty(), "the surface declares no verb {missing:?}");
        probes
    }

    /// 🧪️ [`probe_declared_verbs`] over every declared verb, or — `only` — the agent-lane probe over the named verbs.
    async fn probe_declared_verbs_where<A, M>(definition: fn() -> semio_framework::AppDefinition, examples: Option<&str>, only: Option<&[&str]>) -> Vec<DeclaredVerbProbe>
    where
        A: ArtifactApp + Default,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        use semio_framework::{effective_action_args, resolve_audience, window_kind_actions, DslValue};
        let definition = definition();
        let instances = definition.window_kinds.iter().enumerate().map(|(index, window)| semio_framework::ViewWindowInstance { id: format!("declared-verb-probe-{index}"), window_kind_id: window.id.clone() }).collect::<Vec<_>>();
        let view_of = |index: usize| super::ViewModel {
            active_mode_id: Some(definition.default_mode_id.clone()),
            active_window_kind_id: Some(definition.window_kinds[index].id.clone()),
            window_id: Some(instances[index].id.clone()),
            window_instances: instances.clone(),
            ..super::ViewModel::new(semio_framework_ui_locale::Locale::En, semio_framework_ui_locale::Terminology::Native)
        };
        let examples: serde_json::Value = examples.map(|text| serde_json::from_str(text).expect("declared-verb examples are JSON")).unwrap_or(serde_json::Value::Null);
        let staged_of = |action: &semio_framework::ActionDefinition| {
            let example = examples["verbs"].get(&action.id).map(DslValue::from).unwrap_or(DslValue::Object(Vec::new()));
            effective_action_args(&action.args, &example, None)
        };
        let boot = definition.window_kinds.iter().enumerate().find_map(|(index, window)| {
            window_kind_actions(&definition, window).into_iter().find(|action| action.id == "setActiveExample").map(|action| DeclaredVerbBoot { args: declared_verb_boot_args(action, staged_of(action)), view: view_of(index) })
        });
        let mut order: Vec<(semio_framework::ActionDefinition, Vec<usize>)> = Vec::new();
        for (index, window) in definition.window_kinds.iter().enumerate() {
            for action in window_kind_actions(&definition, window) {
                if super::is_framework_reserved_action_id(&action.id) || matches!(action.id.as_str(), super::SET_ACTIVE_TOOL_ACTION_ID | super::SET_ACTIVE_UTILITY_ACTION_ID) {
                    continue;
                }
                match order.iter_mut().find(|(known, _)| known.id == action.id) {
                    Some((_, windows)) => windows.push(index),
                    None => order.push((action.clone(), vec![index])),
                }
            }
        }
        let mut probes = Vec::new();
        for (action, windows) in &order {
            if only.is_some_and(|only| !only.contains(&action.id.as_str())) {
                continue;
            }
            let boot = if action.id == "setActiveExample" { None } else { boot.as_ref() };
            let audience = resolve_audience(action);
            let staged = staged_of(action);
            let bridge = A::command_from_action(&action.id, Some(&staged)).await.map(drop).map_err(|fault| format!("{}: {}", fault.code.0, fault.message));
            let mut window_probes = Vec::new();
            for index in windows {
                let view = view_of(*index);
                let window = &definition.window_kinds[*index];
                let staged_outcome = declared_verb_dispatch::<A, M>(&definition, boot, &action.id, &staged, &view, &window.body_key).await;
                let mut arguments = Vec::new();
                if only.is_none() && audience != semio_framework::CapabilityAudience::Input && !matches!(staged_outcome, DeclaredVerbOutcome::Unreachable { .. }) {
                    for argument in &action.args {
                        let Some((first, second)) = declared_argument_alternatives(argument) else { continue };
                        let with = |value: DslValue| {
                            let mut args = staged.clone();
                            if let DslValue::Object(entries) = &mut args {
                                entries.retain(|(key, _)| key != &argument.id);
                                entries.push((argument.id.clone(), value));
                            }
                            args
                        };
                        let others_specified = action.args.iter().filter(|other| other.id != argument.id).all(|other| staged.get(&other.id).is_some_and(|value| !matches!(value, DslValue::Null)));
                        let first = declared_verb_dispatch::<A, M>(&definition, boot, &action.id, &with(first), &view, &window.body_key).await;
                        let second = declared_verb_dispatch::<A, M>(&definition, boot, &action.id, &with(second), &view, &window.body_key).await;
                        arguments.push(DeclaredArgumentProbe { argument: argument.id.clone(), others_specified, first, second });
                    }
                }
                window_probes.push(DeclaredVerbWindowProbe { window: window.id.clone(), staged: staged_outcome, arguments });
            }
            let agent = match audience {
                semio_framework::CapabilityAudience::Agent => {
                    let claimed = definition.window_kinds.iter().find(|window| window.actions.iter().any(|claimed| claimed.id == action.id)).map_or("*", |window| window.id.as_str());
                    Some(declared_verb_agent_dispatch::<A, M>(&definition, boot, &action.id, &staged, claimed).await)
                }
                _ => None,
            };
            probes.push(DeclaredVerbProbe { verb: action.id.clone(), kind: action.kind, audience, destructive: action.semantics.effects.destructive, bridge, windows: window_probes, agent });
        }
        probes
    }

    /// ⚖️ Every verb `definition` declares honours its declaration ([`declared_verb_findings`] over
    /// [`probe_declared_verbs`], with the surface's optional example arguments). Answers the probes, so a
    /// caller pins their count and the outcome of the verbs its examples make act — a surface that stops
    /// declaring its verbs or whose examples stop acting cannot turn the law vacuous.
    pub async fn assert_declared_verbs_honour_their_declarations<A, M>(definition: fn() -> semio_framework::AppDefinition, examples: Option<&str>) -> Vec<DeclaredVerbProbe>
    where
        A: ArtifactApp + Default,
        M: super::SpaceMember + super::MemberFactory + Send + 'static,
    {
        let probes = probe_declared_verbs::<A, M>(definition, examples).await;
        let findings = probes.iter().flat_map(declared_verb_findings).filter(|finding| !matches!(finding, DeclaredVerbFinding::AgentLaneDiverges { .. })).map(|finding| finding.to_string()).collect::<Vec<_>>();
        assert!(findings.is_empty(), "{} finding(s) over {} declared verb(s):\n{}", findings.len(), probes.len(), findings.join("\n"));
        probes
    }

    /// 🤖️ The verbs whose agent lane diverges from their shell lane, in probe order — a surface pins
    /// this list so every divergence is named in its own law until the agent lane runs the shell
    /// lane's code (ticket 26/09/23/END-TO-END-OS-HUB-COLLABORATION-MCP, slice P8), and a new one
    /// turns the law red.
    pub fn declared_verb_agent_divergences(probes: &[DeclaredVerbProbe]) -> Vec<String> {
        probes.iter().filter(|probe| declared_verb_findings(probe).iter().any(|finding| matches!(finding, DeclaredVerbFinding::AgentLaneDiverges { .. }))).map(|probe| probe.verb.clone()).collect()
    }

    /// 🔎️ The probe of one declared verb, for a caller pinning what its examples made that verb do.
    pub fn declared_verb_probe<'a>(probes: &'a [DeclaredVerbProbe], verb: &str) -> &'a DeclaredVerbProbe {
        probes.iter().find(|probe| probe.verb == verb).unwrap_or_else(|| panic!("verb {verb} was not probed"))
    }

    /// 📝️ Whether this outcome settled and wrote or replaced the document.
    pub fn declared_verb_wrote_document(outcome: &DeclaredVerbOutcome) -> bool {
        matches!(outcome, DeclaredVerbOutcome::Settled(effect) if effect.touches_document())
    }

    /// 📝️ Whether the verb's staged invocation wrote or replaced the document from any window.
    pub fn declared_verb_staged_wrote_document(probe: &DeclaredVerbProbe) -> bool {
        probe.windows.iter().any(|window| declared_verb_wrote_document(&window.staged))
    }

    /// 📝️ Whether any invocation of the verb, staged or perturbed, wrote or replaced the document.
    pub fn declared_verb_ever_wrote_document(probe: &DeclaredVerbProbe) -> bool {
        probe.windows.iter().any(|window| declared_verb_wrote_document(&window.staged) || window.arguments.iter().any(|argument| declared_verb_wrote_document(&argument.first) || declared_verb_wrote_document(&argument.second)))
    }

