//#region 🔖️DocumentContract
/// 🧾️ Read-only view of an app's document handed to `ArtifactApp::handle_action`/`render`:
/// the materialized snapshot plus the history metadata (checkpoints/alternatives/undo state)
/// derived from the owning {@link VcsArtifactApp}'s persistent {@link ArtifactStore}.
pub struct ArtifactView<'a, P> {
    pub snapshot: &'a P,
    pub history: &'a HistoryView,
    /// 🧸️ Read access to this document's OWNED CHILDREN, each of which is its own envelope with
    /// its own `ArtifactVcs` history (never an inline subtree). See {@link ChildContentView}.
    pub children: ChildContentView,
    operation: Option<AppOperationContext>,
    render_operation: Option<AppRenderOperationContext>,
    parent_document_id: Option<String>,
    snapshot_read: std::sync::Mutex<Option<store::SnapshotRead<P>>>,
    tool_run: Option<ToolRunView>,
    operations: &'a [ArtifactOperationProgress],
    provisional_generation: u64,
}

/// 🪪️ Durable authority captured once at public command admission and copied into every
/// plugin continuation record.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AppOperationContext {
    pub app_instance_id: u32,
    pub parent_document_id: String,
    pub operation_id: u64,
    pub generation: u64,
    pub canonical_base_revision: [u8; 32],
    /// 🪪️ Who admitted this command, and when: content-addressed over the admitting actor and the document
    /// store's hybrid logical clock ticked for the admission (`VcsArtifactApp::authoring_seed`). Every id a
    /// command mints is scoped by it, so two writers — or two sessions of one — never mint the same id at one base.
    pub authoring_seed: String,
}

/// 🎨️ Fixed authority for one live renderer-observed document revision. Unlike a command
/// operation, this carries no user invocation id: it binds an app-owned retained background job to
/// the exact instance, base revision and store generation observed by the renderer/refresh pass.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct AppRenderOperationContext {
    pub app_instance_id: u32,
    pub base_revision: semio_framework_job::RevisionId,
    pub generation: semio_framework_job::Generation,
    pub canonical_base_revision: [u8; 32],
}

/// 🧾️ Projects the exact render-pinned store revision onto the decimal-u64 completion lane.
pub fn render_operation_publication_revision(operation: AppRenderOperationContext) -> semio_framework_ui_contract::UiPublicationRevision {
    semio_framework_ui_contract::UiPublicationRevision(u64::from_be_bytes(operation.canonical_base_revision[..8].try_into().expect("revision lane width")))
}

/// 🧾️ Reads the render-pinned store authority required by editable retained controls.
pub fn artifact_render_publication_revision<P>(doc: &ArtifactView<'_, P>) -> super::UiAssemblyResult<semio_framework_ui_contract::UiPublicationRevision> {
    doc.render_operation().map(render_operation_publication_revision).ok_or_else(|| super::PluginAssemblyError::new("framework.artifact-render.publication-revision", "editable rendering requires a render-pinned document revision"))
}

impl AppOperationContext {
    /// 🧬️ Fixed-width lowercase encoding for typed persisted continuation fields.
    pub fn canonical_base_revision_hex(&self) -> String {
        const HEX: &[u8; 16] = b"0123456789abcdef";
        let mut result = String::with_capacity(64);
        for byte in self.canonical_base_revision {
            result.push(HEX[usize::from(byte >> 4)] as char);
            result.push(HEX[usize::from(byte & 0x0f)] as char);
        }
        result
    }
}

impl<'a, P> ArtifactView<'a, P> {
    /// 🏗️ A view over a document with no composed children — the overwhelming majority, and the
    /// shape every leaf app and test uses. Prefer this over a struct literal: lane views grow
    /// over time, and a constructor absorbs that growth without touching every call site.
    pub fn new(snapshot: &'a P, history: &'a HistoryView) -> Self {
        Self { snapshot, history, children: ChildContentView::EMPTY, operation: None, render_operation: None, parent_document_id: None, snapshot_read: std::sync::Mutex::new(None), tool_run: None, operations: &[], provisional_generation: 0 }
    }

    /// 🪪️ Synchronous retained-worker view bound to one exact admitted operation.
    pub fn with_operation(snapshot: &'a P, history: &'a HistoryView, operation: AppOperationContext) -> Self {
        Self {
            snapshot,
            history,
            children: ChildContentView::EMPTY,
            operation: Some(operation),
            render_operation: None,
            parent_document_id: None,
            snapshot_read: std::sync::Mutex::new(None),
            tool_run: None,
            operations: &[],
            provisional_generation: 0,
        }
    }

    /// 🧩️ App-side composing view for retained command work, which observes its children through
    /// [`ArtifactOwnedToolJobContext::children`] rather than through a host render pass and so
    /// carries no render identity. Synchronous on purpose: it only moves owned fields.
    pub fn with_children(snapshot: &'a P, history: &'a HistoryView, children: ChildContentView) -> Self {
        Self { snapshot, history, children, operation: None, render_operation: None, parent_document_id: None, snapshot_read: std::sync::Mutex::new(None), tool_run: None, operations: &[], provisional_generation: 0 }
    }

    /// 🪪️ Binds a composing retained view to the exact admitted operation it runs under, so its handlers mint ids
    /// and tool transactions from the admission's authoring seed exactly like a leaf view bound by `with_operation`.
    pub fn bound_to_operation(mut self, operation: AppOperationContext) -> Self {
        self.operation = Some(operation);
        self
    }

    /// 🏗️ A view over a composing document, wired to its live child stores AND to the identity the
    /// live revision is observed under. Every host entry point that hands an app a composing view —
    /// `render`, `pending_effects`, `window_engagements`, `window_measures`, `tool_measures`,
    /// `context_menu`, `interaction_topology`, `export_media`, `media_fingerprint` — goes through
    /// here, so [`ArtifactView::render_operation`] is total on the host and an app that leases a
    /// per-instance session off it (puzzle 3d's `puzzle3d_view_session_key`) never runs cold.
    async fn with_render_context(snapshot: &'a P, history: &'a HistoryView, children: ChildContentView, render_operation: AppRenderOperationContext, parent_document_id: String, snapshot_read: Option<store::SnapshotRead<P>>) -> Self {
        Self {
            snapshot,
            history,
            children,
            operation: None,
            render_operation: Some(render_operation),
            parent_document_id: Some(parent_document_id),
            snapshot_read: std::sync::Mutex::new(snapshot_read),
            tool_run: None,
            operations: &[],
            provisional_generation: 0,
        }
    }

    /// ⏯️ Binds the tool run this document instance shows; `snapshot` is then committed ⊕ provisional.
    fn with_tool_run(mut self, tool_run: Option<ToolRunView>) -> Self {
        self.tool_run = tool_run;
        self
    }

    /// ⏯️ The run whose provisional entities render with the `provisional` style token and stay
    /// out of interaction topology (contract §4.1 layer 1).
    pub fn tool_run(&self) -> Option<&ToolRunView> {
        self.tool_run.as_ref()
    }

    /// 🔢️ Binds the instance's continuous-tool overlay generation, which moves on every tick, release and zero-trace
    /// abort of an open press or typing run.
    fn with_provisional_generation(mut self, generation: u64) -> Self {
        self.provisional_generation = generation;
        self
    }

    /// 🔢️ The continuous-tool overlay generation as of this view: a derived view (a preview) whose input follows the
    /// open transactions (`ArtifactOwnedToolJobContext::provisional`) owes a fresh evaluation whenever it moves, even
    /// when no edit landed (a zero-trace abort).
    pub fn provisional_generation(&self) -> u64 {
        self.provisional_generation
    }

    /// ⏳️ Current local command work; observation never enters artifact history.
    pub fn operations(&self) -> &[ArtifactOperationProgress] {
        self.operations
    }

    fn with_operations(mut self, operations: &'a [ArtifactOperationProgress]) -> Self {
        self.operations = operations;
        self
    }

    /// 🪪️ Returns the actual public job authority for command handlers.
    pub fn operation(&self) -> Result<&AppOperationContext, Fault> {
        self.operation.as_ref().ok_or_else(|| plugin_sdk_fault("the artifact view is not bound to a public command operation"))
    }

    /// 🪪️ Optional form for render/test-only views which do not enter command authority.
    pub fn operation_optional(&self) -> Option<&AppOperationContext> {
        self.operation.as_ref()
    }

    /// 🎨️ Returns the immutable identity observed by a live render/refresh pass.
    pub fn render_operation(&self) -> Option<AppRenderOperationContext> {
        self.render_operation
    }

    /// 🧾️ Returns the exact live store envelope id bound to this host render pass.
    pub fn parent_document_id(&self) -> Option<&str> {
        self.parent_document_id.as_deref()
    }

    /// 🧵️ Transfers the one registered immutable snapshot-read lease to a retained worker
    /// owner. Contention and a second take fail closed without cloning the underlying snapshot.
    pub fn take_snapshot_read(&self) -> Result<store::SnapshotRead<P>, Fault> {
        let mut owner = self.snapshot_read.try_lock().map_err(|_| plugin_sdk_fault("the live snapshot-read lease is busy"))?;
        owner.take().ok_or_else(|| plugin_sdk_fault("the artifact view has no transferable live snapshot-read lease"))
    }
}

/// 🧸️ Read-only access to a composing document's live child stores, keyed `(slot,
/// child_id)` exactly as the parent's `ArtifactChild` handles name them.
///
/// This is the seam that replaces the `thread_local!`/session `HashMap<child_id, content>`
/// caches every composed plugin used to carry. Those caches went STALE the moment anything
/// moved a child's history without going through `ArtifactApp::handle` — store-level undo/redo
/// and checkout do exactly that. `new` clones every live `SpaceMember`'s already-owned snapshot
/// `Arc` and fixed-size revision ONCE, without encoding or graph cloning, so a view built fresh
/// immediately before each `handle`/`render` call (as every {@link VcsArtifactApp} call site
/// does) cannot present state older than the dispatch it belongs to.
///
/// 🚫️async: E1-adjacent by construction, not tagged — `M: SpaceMember` is generic on {@link
/// Self::new} itself, NOT on this struct. `ArtifactApp::render`/`handle`/… fix their `doc`
/// parameter's type at exactly `ArtifactView<'_, Self::Snapshot>` (no member-kind parameter),
/// so `ChildContentView` must stay a single, non-generic, dyn-free type usable from EVERY
/// plugin's fixed trait-method signature — the old `Box<dyn SpaceMember>` erasure existed
/// precisely to buy that uniformity, which is no longer available once `SpaceMember` is AFIT
/// (not object-safe). Pre-extracting each child's immutable snapshot handle at `new()` time (function-generic
/// over the caller's concrete `M`) reproduces the same uniformity without a trait object or a
/// fleet-wide `ArtifactApp::Members` associated-type rollout — see
/// `📓️terra-dedyn-fw-os-spacemember-report.md` §ChildContentView for the rejected alternatives.
/// `Default` (`EMPTY`) so a leaf app's view costs nothing and needs no ceremony.
const CHILD_CONTENT_SLOTS: usize = 1_024;
const CHILD_CONTENT_PAGE_SLOTS: usize = 32;
const CHILD_CONTENT_PAGES: usize = CHILD_CONTENT_SLOTS / CHILD_CONTENT_PAGE_SLOTS;
const CHILD_CONTENT_ID_BYTES: usize = 256;
const OWNED_DOCUMENT_MEMBER_PREPARATION_BYTES: usize = store::MEMBER_OPEN_IDENTITY_BYTES * 8;

pub(crate) struct ChildMemberEntry<M> {
    pub(crate) reference: ArtifactRef,
    pub(crate) owner: store::OwnerRef,
    pub(crate) member: M,
}

struct ChildMemberAdmission {
    index: usize,
    generation: u64,
}

pub struct ChildMemberRegistrationError<M> {
    pub member: Option<M>,
    pub fault: Fault,
}

impl<M> std::fmt::Debug for ChildMemberRegistrationError<M> {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.debug_struct("ChildMemberRegistrationError").field("owner_returned", &self.member.is_some()).field("fault", &self.fault).finish()
    }
}

pub(crate) struct ChildMemberRegistry<M> {
    slots: Box<[std::mem::MaybeUninit<ChildMemberEntry<M>>]>,
    occupied: [u64; CHILD_CONTENT_SLOTS / 64],
    reserved: [u64; CHILD_CONTENT_SLOTS / 64],
    generations: [u64; CHILD_CONTENT_SLOTS],
    dense_slots: [usize; CHILD_CONTENT_SLOTS],
    ordinal_by_slot: [usize; CHILD_CONTENT_SLOTS],
    next_generation: u64,
    len: usize,
    allocation_admitted: bool,
}

impl<M> ChildMemberRegistry<M> {
    fn new() -> Self {
        let mut slots = Vec::new();
        let allocation_admitted = slots.try_reserve_exact(CHILD_CONTENT_SLOTS).is_ok();
        if allocation_admitted {
            slots.resize_with(CHILD_CONTENT_SLOTS, std::mem::MaybeUninit::uninit);
        }
        Self {
            slots: slots.into_boxed_slice(),
            occupied: [0; CHILD_CONTENT_SLOTS / 64],
            reserved: [0; CHILD_CONTENT_SLOTS / 64],
            generations: [0; CHILD_CONTENT_SLOTS],
            dense_slots: [usize::MAX; CHILD_CONTENT_SLOTS],
            ordinal_by_slot: [usize::MAX; CHILD_CONTENT_SLOTS],
            next_generation: 0,
            len: 0,
            allocation_admitted,
        }
    }

    fn hash(slot: &str, child_id: &str) -> Result<usize, Fault> {
        ChildContentView::hash(slot, child_id)
    }

    fn occupied(&self, index: usize) -> bool {
        self.occupied[index / 64] & (1 << (index % 64)) != 0
    }

    fn reserved(&self, index: usize) -> bool {
        self.reserved[index / 64] & (1 << (index % 64)) != 0
    }

    fn entry(&self, index: usize) -> Option<&ChildMemberEntry<M>> {
        self.occupied(index).then(|| unsafe { self.slots[index].assume_init_ref() })
    }

    fn entry_mut(&mut self, index: usize) -> Option<&mut ChildMemberEntry<M>> {
        if !self.occupied(index) {
            return None;
        }
        Some(unsafe { self.slots[index].assume_init_mut() })
    }

    fn locate(&self, slot: &str, child_id: &str) -> Result<Result<usize, usize>, Fault> {
        if !self.allocation_admitted {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-allocation"), "fixed child-member registry allocation was not pre-admitted"));
        }
        let start = Self::hash(slot, child_id)?;
        for offset in 0..CHILD_CONTENT_SLOTS {
            let index = (start + offset) % CHILD_CONTENT_SLOTS;
            match self.entry(index) {
                Some(candidate) if candidate.owner.slot == slot && candidate.owner.child_id == child_id => return Ok(Ok(index)),
                Some(_) => {}
                None if self.reserved(index) => {}
                None => return Ok(Err(index)),
            }
        }
        Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-capacity"), "fixed child-member registry is saturated"))
    }

    fn admit_identity(&mut self, slot: &str, child_id: &str) -> Result<ChildMemberAdmission, Fault> {
        if !self.allocation_admitted {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-allocation"), "fixed child-member registry allocation was not pre-admitted"));
        }
        match self.locate(slot, child_id)? {
            Ok(_) => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-duplicate"), "fixed child-member identity is already occupied")),
            Err(index) => {
                let generation = self.next_generation.checked_add(1).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-generation"), "fixed child-member admission generation exhausted"))?;
                self.next_generation = generation;
                self.generations[index] = generation;
                self.reserved[index / 64] |= 1 << (index % 64);
                Ok(ChildMemberAdmission { index, generation })
            }
        }
    }

    fn admit(&mut self, key: &(String, String)) -> Result<ChildMemberAdmission, Fault> {
        self.admit_identity(&key.0, &key.1)
    }

    #[expect(clippy::needless_pass_by_value, reason = "This non-Copy token conveys one-use admission authority and must be consumed by the commit, even though its identity fields are scalar.")]
    fn insert_admitted(&mut self, admission: ChildMemberAdmission, reference: ArtifactRef, owner: store::OwnerRef, member: M) {
        assert!(self.reserved(admission.index) && self.generations[admission.index] == admission.generation && !self.occupied(admission.index), "exact child-member admission changed while its exclusive app owner was suspended");
        self.reserved[admission.index / 64] &= !(1 << (admission.index % 64));
        self.slots[admission.index].write(ChildMemberEntry { reference, owner, member });
        self.occupied[admission.index / 64] |= 1 << (admission.index % 64);
        self.dense_slots[self.len] = admission.index;
        self.ordinal_by_slot[admission.index] = self.len;
        self.len += 1;
    }

    pub(crate) fn get(&self, key: &(String, String)) -> Option<&ChildMemberEntry<M>> {
        let Ok(Ok(index)) = self.locate(&key.0, &key.1) else { return None };
        self.entry(index)
    }

    pub(crate) fn get_mut(&mut self, key: &(String, String)) -> Option<&mut ChildMemberEntry<M>> {
        let Ok(Ok(index)) = self.locate(&key.0, &key.1) else { return None };
        self.entry_mut(index)
    }

    pub(crate) fn entries(&self) -> impl Iterator<Item = &ChildMemberEntry<M>> {
        self.dense_slots[..self.len].iter().map(|index| self.entry(*index).expect("dense child-member slot remains occupied"))
    }

    fn entries_physical(&self) -> impl Iterator<Item = &ChildMemberEntry<M>> {
        let occupied = self.occupied;
        self.slots.iter().enumerate().filter(move |(index, _)| occupied[*index / 64] & (1 << (*index % 64)) != 0).map(|(_, slot)| unsafe { slot.assume_init_ref() })
    }

    fn entries_mut_physical(&mut self) -> impl Iterator<Item = &mut ChildMemberEntry<M>> {
        let occupied = self.occupied;
        self.slots.iter_mut().enumerate().filter_map(move |(index, slot)| (occupied[index / 64] & (1 << (index % 64)) != 0).then(|| unsafe { slot.assume_init_mut() }))
    }

    fn entry_by_ordinal(&self, ordinal: usize) -> Option<&ChildMemberEntry<M>> {
        (ordinal < self.len).then(|| self.entry(self.dense_slots[ordinal]).expect("dense child-member slot remains occupied"))
    }

    fn take_at(&mut self, index: usize) -> Option<ChildMemberEntry<M>> {
        if !self.occupied(index) {
            return None;
        }
        self.occupied[index / 64] &= !(1 << (index % 64));
        self.len -= 1;
        let ordinal = self.ordinal_by_slot[index];
        let moved = self.dense_slots[self.len];
        self.dense_slots[ordinal] = moved;
        self.ordinal_by_slot[moved] = ordinal;
        self.dense_slots[self.len] = usize::MAX;
        self.ordinal_by_slot[index] = usize::MAX;
        Some(unsafe { self.slots[index].assume_init_read() })
    }

    fn cancel_admission(&mut self, admission: &ChildMemberAdmission) -> bool {
        if !self.reserved(admission.index) || self.generations[admission.index] != admission.generation {
            return false;
        }
        self.reserved[admission.index / 64] &= !(1 << (admission.index % 64));
        true
    }

    fn has_admission_in_flight(&self) -> bool {
        self.reserved.iter().any(|word| *word != 0)
    }

    /// 🍂️ Removes one exact member while no admission is in flight and re-seats every later entry of its probe
    /// run (backward shift), so every other member stays addressable by [`Self::locate`].
    fn remove(&mut self, slot: &str, child_id: &str) -> Result<Option<ChildMemberEntry<M>>, Fault> {
        if self.has_admission_in_flight() {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-removal-admission"), "a child member cannot leave the fixed registry while an admission is in flight"));
        }
        let Ok(mut hole) = self.locate(slot, child_id)? else { return Ok(None) };
        let entry = self.take_at(hole).expect("located child member remains occupied");
        let mut cursor = (hole + 1) % CHILD_CONTENT_SLOTS;
        while let Some(moved) = self.entry(cursor) {
            let home = Self::hash(&moved.owner.slot, &moved.owner.child_id)?;
            if (cursor + CHILD_CONTENT_SLOTS - home) % CHILD_CONTENT_SLOTS >= (cursor + CHILD_CONTENT_SLOTS - hole) % CHILD_CONTENT_SLOTS {
                self.relocate(cursor, hole);
                hole = cursor;
            }
            cursor = (cursor + 1) % CHILD_CONTENT_SLOTS;
        }
        Ok(Some(entry))
    }

    fn relocate(&mut self, from: usize, to: usize) {
        let entry = unsafe { self.slots[from].assume_init_read() };
        self.slots[to].write(entry);
        self.occupied[from / 64] &= !(1 << (from % 64));
        self.occupied[to / 64] |= 1 << (to % 64);
        self.generations[to] = self.generations[from];
        let ordinal = self.ordinal_by_slot[from];
        self.dense_slots[ordinal] = to;
        self.ordinal_by_slot[to] = ordinal;
        self.ordinal_by_slot[from] = usize::MAX;
    }

    pub(crate) fn len(&self) -> usize {
        self.len
    }

    pub(crate) fn is_empty(&self) -> bool {
        self.len == 0
    }
}

impl<M> Drop for ChildMemberRegistry<M> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || self.is_empty(), "fixed child-member registry reached Drop before every exact member was transferred to bounded retirement");
        assert!(std::thread::panicking() || self.reserved.iter().all(|word| *word == 0), "fixed child-member registry reached Drop with a reserved owner slot outside exact admission");
        assert!(
            std::thread::panicking() || self.dense_slots.iter().all(|slot| *slot == usize::MAX) && self.ordinal_by_slot.iter().all(|ordinal| *ordinal == usize::MAX),
            "fixed child-member registry reached Drop with a stale dense owner coordinate"
        );
    }
}

/// 📥️ Retains one exact recursive member identity with its admitted bounded open request.
pub struct OwnedDocumentMemberIngress {
    identity: std::mem::ManuallyDrop<Option<(usize, ArtifactRef, store::OwnerRef)>>,
    request: std::mem::ManuallyDrop<Option<store::MemberOpenRequest>>,
    identity_field: u8,
}

impl OwnedDocumentMemberIngress {
    /// 🪪️ Binds one closure ordinal and recursive owner to the request's sealed identity.
    #[expect(clippy::result_large_err, reason = "Rejected ingress returns its exact retained page and identity owners unchanged.")]
    pub fn try_new(ordinal: usize, reference: ArtifactRef, owner: store::OwnerRef, request: store::MemberOpenRequest) -> Result<Self, (Fault, Self)> {
        let ingress = Self { identity: std::mem::ManuallyDrop::new(Some((ordinal, reference, owner))), request: std::mem::ManuallyDrop::new(Some(request)), identity_field: 0 };
        let (_, reference, owner) = ingress.identity.as_ref().expect("fresh member ingress retains identity");
        let request = ingress.request.as_ref().expect("fresh member ingress retains request");
        let valid = ordinal < store::OWNED_DOCUMENT_MAXIMUM_MEMBERS && request.admitted_expected().is_ok() && request.expected() == reference && request.owner() == Some(owner);
        if valid {
            Ok(ingress)
        } else {
            Err((plugin_sdk_fault("owned document member ingress identity, owner, ordinal, or admitted request does not match"), ingress))
        }
    }

    fn ordinal(&self) -> usize {
        self.identity.as_ref().expect("live member ingress retains identity").0
    }

    fn operation(&self) -> semio_framework_job::OperationId {
        self.request.as_ref().expect("live member ingress retains request").operation()
    }

    fn generation(&self) -> semio_framework_job::Generation {
        self.request.as_ref().expect("live member ingress retains request").generation()
    }

    fn take_request(&mut self) -> Option<store::MemberOpenRequest> {
        self.request.take()
    }

    fn has_request(&self) -> bool {
        self.request.is_some()
    }

    fn return_request(&mut self, request: store::MemberOpenRequest) {
        assert!(self.request.is_none(), "member ingress request can only return to its exact empty slot");
        *self.request = Some(request);
    }

    fn take_identity(&mut self) -> Option<(usize, ArtifactRef, store::OwnerRef)> {
        self.identity.take()
    }

    fn has_identity(&self) -> bool {
        self.identity.is_some()
    }

    fn identity_string_mut(&mut self) -> Option<&mut String> {
        let (_, reference, owner) = self.identity.as_mut()?;
        match self.identity_field {
            0 => Some(&mut reference.artifact_id),
            1 => Some(&mut reference.dialect.artifact_kind),
            2 => Some(&mut reference.dialect.standard),
            3 => Some(&mut reference.dialect.subset),
            4 => Some(&mut owner.parent.artifact_id),
            5 => Some(&mut owner.parent.dialect.artifact_kind),
            6 => Some(&mut owner.parent.dialect.standard),
            7 => Some(&mut owner.parent.dialect.subset),
            8 => Some(&mut owner.slot),
            9 => Some(&mut owner.child_id),
            _ => None,
        }
    }

    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
        if maximum_items == 0 {
            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(request) = self.request.as_mut() {
            return match request.close_step(1, maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))? {
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= 1 && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                store::SnapshotRetirementStep::Pending { .. } => Err(plugin_sdk_fault("member ingress request exceeded its close grant")),
                store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "member ingress request retirement is blocked" }),
                store::SnapshotRetirementStep::Complete if request.terminal_is_empty() => {
                    drop(self.request.take());
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                store::SnapshotRetirementStep::Complete => Err(plugin_sdk_fault("member ingress request returned false terminal")),
            };
        }
        while self.identity_field < 10 && self.identity_string_mut().is_some_and(|field| field.is_empty()) {
            self.identity_field += 1;
        }
        if let Some(field) = self.identity_string_mut() {
            let bytes = field.chars().next_back().map_or(0, char::len_utf8);
            if bytes > maximum_bytes {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            field.pop();
            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: bytes });
        }
        if let Some(identity) = self.identity.take() {
            drop(identity);
            return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(PluginCloseStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.identity.is_none() && self.request.is_none()
    }
}

impl Drop for OwnedDocumentMemberIngress {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || self.terminal_is_empty(), "owned document member ingress reached Drop before exact handoff or bounded close");
    }
}

struct OwnedDocumentMemberIngressRegistry {
    slots: Box<[std::mem::MaybeUninit<OwnedDocumentMemberIngress>]>,
    occupied: [u64; CHILD_CONTENT_SLOTS / 64],
    expected: usize,
    len: usize,
    generation: u64,
    sealed: bool,
    close_cursor: usize,
}

impl OwnedDocumentMemberIngressRegistry {
    fn try_new(expected: usize) -> Result<Self, Fault> {
        if expected > store::OWNED_DOCUMENT_MAXIMUM_MEMBERS {
            return Err(plugin_sdk_fault("owned document member ingress exceeds the recursive closure member limit"));
        }
        let mut slots = Vec::new();
        slots.try_reserve_exact(expected).map_err(|_| plugin_sdk_fault("owned document member ingress allocation was not admitted"))?;
        slots.resize_with(expected, std::mem::MaybeUninit::uninit);
        Ok(Self { slots: slots.into_boxed_slice(), occupied: [0; CHILD_CONTENT_SLOTS / 64], expected, len: 0, generation: 0, sealed: false, close_cursor: 0 })
    }

    #[expect(clippy::result_large_err, reason = "Refusal returns the exact retained member ingress owner unchanged.")]
    fn admit(&mut self, ingress: OwnedDocumentMemberIngress) -> Result<(), (Fault, OwnedDocumentMemberIngress)> {
        let ordinal = ingress.ordinal();
        if self.sealed || ordinal >= self.expected || self.occupied[ordinal / 64] & (1 << (ordinal % 64)) != 0 {
            return Err((plugin_sdk_fault("owned document member ingress is sealed, out of range, or duplicates an ordinal"), ingress));
        }
        let Some(generation) = self.generation.checked_add(1) else {
            return Err((plugin_sdk_fault("owned document member ingress generation exhausted"), ingress));
        };
        self.slots[ordinal].write(ingress);
        self.occupied[ordinal / 64] |= 1 << (ordinal % 64);
        self.len += 1;
        self.generation = generation;
        Ok(())
    }

    fn seal(&mut self) -> Result<(), Fault> {
        if self.sealed || self.len != self.expected {
            return Err(plugin_sdk_fault("owned document member ingress is duplicate-sealed or incomplete"));
        }
        self.sealed = true;
        Ok(())
    }

    fn take(&mut self, ordinal: usize) -> Option<OwnedDocumentMemberIngress> {
        if ordinal >= self.expected || self.occupied[ordinal / 64] & (1 << (ordinal % 64)) == 0 {
            return None;
        }
        self.occupied[ordinal / 64] &= !(1 << (ordinal % 64));
        self.len -= 1;
        Some(unsafe { self.slots[ordinal].assume_init_read() })
    }

    /// ♻️ Closes the occupied slots in place, ordinal by ordinal, under the caller's
    /// grant. The ingress being retired is never lifted into a field of this registry: one
    /// `MemberOpenRequest` inline would put the whole registry shell past a kilobyte of stack,
    /// while the 1,024 request slots themselves are already behind the single `slots` heap
    /// owner. The slot is detached only once its own `close_step` answers `Complete` with a
    /// truthful terminal witness, so a refusal leaves the request exactly where it was.
    ///
    /// SAFETY: the occupancy bit is set only after `write` and cleared before `assume_init_read`.
    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
        while self.close_cursor < self.expected {
            let ordinal = self.close_cursor;
            if self.occupied[ordinal / 64] & (1 << (ordinal % 64)) == 0 {
                self.close_cursor += 1;
                continue;
            }
            let active = unsafe { self.slots[ordinal].assume_init_mut() };
            let step = active.close_step(maximum_items, maximum_bytes)?;
            if step != PluginCloseStep::Complete {
                return Ok(step);
            }
            if !active.terminal_is_empty() {
                return Err(plugin_sdk_fault("member ingress close returned false terminal"));
            }
            let retired = self.take(ordinal).ok_or_else(|| plugin_sdk_fault("member ingress close lost its exact occupied ordinal"))?;
            drop(retired);
            self.close_cursor += 1;
            return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(PluginCloseStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.len == 0
    }
}

impl Drop for OwnedDocumentMemberIngressRegistry {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || self.terminal_is_empty(), "owned document member ingress registry reached Drop before every request owner was handed off or bounded-closed");
    }
}

struct DocumentClosureSourceView<'a, P, M> {
    generation: u64,
    root_reference: &'a ArtifactRef,
    root_snapshot: &'a P,
    members: &'a ChildMemberRegistry<M>,
}

impl<'a, P, M> DocumentClosureSourceView<'a, P, M> {
    fn new(generation: u64, root_reference: &'a ArtifactRef, root_snapshot: &'a P, members: &'a ChildMemberRegistry<M>) -> Self {
        Self { generation, root_reference, root_snapshot, members }
    }
}

impl<P, M> store::OwnedDocumentClosureSource for DocumentClosureSourceView<'_, P, M>
where
    P: semio_framework_schema_composition::ArtifactCompositionFields,
    M: SpaceMember,
{
    fn generation(&self) -> u64 {
        self.generation
    }

    fn root_reference(&self) -> &ArtifactRef {
        self.root_reference
    }

    fn member_count(&self) -> usize {
        self.members.len()
    }

    fn member_reference(&self, index: usize) -> Option<&ArtifactRef> {
        self.members.entry_by_ordinal(index).map(|entry| &entry.reference)
    }

    fn member_owner(&self, index: usize) -> Option<&store::OwnerRef> {
        self.members.entry_by_ordinal(index).map(|entry| &entry.owner)
    }

    fn child_projection(&self, parent: Option<usize>) -> Result<store::ChildRestoreProjection<'_>, store::ChildRestoreProjectionError> {
        match parent {
            None => store::ChildRestoreProjection::from_snapshot(self.root_snapshot),
            Some(index) => self.members.entry_by_ordinal(index).ok_or(store::ChildRestoreProjectionError::IncompleteSet)?.member.child_restore_projection(),
        }
    }
}

