pub(crate) struct ChildContentEntry {
    slot: String,
    child_id: String,
    dialect: ArtifactDialect,
    revision: [u8; 32],
    pub(crate) snapshot: store::ErasedSnapshotRead,
}

#[derive(Clone)]
struct ChildContentPage {
    entries: [Option<std::sync::Arc<ChildContentEntry>>; CHILD_CONTENT_PAGE_SLOTS],
}

impl Default for ChildContentPage {
    fn default() -> Self {
        Self { entries: std::array::from_fn(|_| None) }
    }
}

#[derive(Clone)]
pub(crate) struct ChildContentRoot {
    pages: [Option<std::sync::Arc<ChildContentPage>>; CHILD_CONTENT_PAGES],
    len: usize,
}

impl Default for ChildContentRoot {
    fn default() -> Self {
        Self { pages: std::array::from_fn(|_| None), len: 0 }
    }
}

#[derive(Clone, Default)]
pub struct ChildContentView {
    pub(crate) root: Option<std::sync::Arc<ChildContentRoot>>,
}

impl ChildContentView {
    /// 🈳️ The view a document with no children gets.
    pub const EMPTY: Self = Self { root: None };

    fn hash(slot: &str, child_id: &str) -> Result<usize, Fault> {
        if slot.len() > CHILD_CONTENT_ID_BYTES || child_id.len() > CHILD_CONTENT_ID_BYTES {
            return Err(plugin_sdk_fault("child slot or id exceeds the fixed immutable-root identity bound"));
        }
        let mut hash = 0xcbf29ce484222325u64;
        for byte in slot.bytes().chain(std::iter::once(0xff)).chain(child_id.bytes()) {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(0x100000001b3);
        }
        Ok(hash as usize % CHILD_CONTENT_SLOTS)
    }

    fn entry_at(root: &ChildContentRoot, index: usize) -> Option<&std::sync::Arc<ChildContentEntry>> {
        root.pages[index / CHILD_CONTENT_PAGE_SLOTS].as_ref()?.entries[index % CHILD_CONTENT_PAGE_SLOTS].as_ref()
    }

    fn locate(root: &ChildContentRoot, slot: &str, child_id: &str) -> Result<Result<usize, usize>, Fault> {
        let start = Self::hash(slot, child_id)?;
        for offset in 0..CHILD_CONTENT_SLOTS {
            let index = (start + offset) % CHILD_CONTENT_SLOTS;
            match Self::entry_at(root, index) {
                Some(entry) if entry.slot == slot && entry.child_id == child_id => return Ok(Ok(index)),
                Some(_) => {}
                None => return Ok(Err(index)),
            }
        }
        Err(plugin_sdk_fault("fixed immutable child-content root is saturated"))
    }

    fn admit_member(&self, slot: &str, child_id: &str) -> Result<usize, Fault> {
        match self.root.as_deref() {
            Some(root) => Self::locate(root, slot, child_id).map(|location| match location {
                Ok(index) | Err(index) => index,
            }),
            None => Self::hash(slot, child_id),
        }
    }

    fn insert_entry_admitted(&self, index: usize, entry: ChildContentEntry) -> Self {
        let root = self.root.as_deref().cloned().unwrap_or_default();
        let page_index = index / CHILD_CONTENT_PAGE_SLOTS;
        let entry_index = index % CHILD_CONTENT_PAGE_SLOTS;
        let mut next = root;
        let mut page = next.pages[page_index].as_deref().cloned().unwrap_or_default();
        let added = page.entries[entry_index].is_none();
        page.entries[entry_index] = Some(std::sync::Arc::new(entry));
        next.pages[page_index] = Some(std::sync::Arc::new(page));
        next.len += usize::from(added);
        Self { root: Some(std::sync::Arc::new(next)) }
    }

    fn find(&self, slot: &str, child_id: &str) -> Result<Option<&ChildContentEntry>, Fault> {
        let Some(root) = self.root.as_deref() else { return Ok(None) };
        match Self::locate(root, slot, child_id)? {
            Ok(index) => Ok(Self::entry_at(root, index).map(std::sync::Arc::as_ref)),
            Err(_) => Ok(None),
        }
    }

    fn set_entry(root: &mut ChildContentRoot, index: usize, entry: Option<std::sync::Arc<ChildContentEntry>>) {
        let page_index = index / CHILD_CONTENT_PAGE_SLOTS;
        let mut page = root.pages[page_index].as_deref().cloned().unwrap_or_default();
        page.entries[index % CHILD_CONTENT_PAGE_SLOTS] = entry;
        root.pages[page_index] = page.entries.iter().any(Option::is_some).then(|| std::sync::Arc::new(page));
    }

    /// 🍂️ The same immutable root without one exact child: a copy-on-write removal that re-seats every later
    /// entry of that child's probe run (backward shift), so every other child stays addressable.
    fn without_member(&self, slot: &str, child_id: &str) -> Result<Self, Fault> {
        let Some(current) = self.root.as_deref() else { return Ok(self.clone()) };
        let Ok(mut hole) = Self::locate(current, slot, child_id)? else { return Ok(self.clone()) };
        let mut next = current.clone();
        Self::set_entry(&mut next, hole, None);
        next.len -= 1;
        let mut cursor = (hole + 1) % CHILD_CONTENT_SLOTS;
        while let Some(entry) = Self::entry_at(&next, cursor).cloned() {
            let home = Self::hash(&entry.slot, &entry.child_id)?;
            if (cursor + CHILD_CONTENT_SLOTS - home) % CHILD_CONTENT_SLOTS >= (cursor + CHILD_CONTENT_SLOTS - hole) % CHILD_CONTENT_SLOTS {
                Self::set_entry(&mut next, hole, Some(entry));
                Self::set_entry(&mut next, cursor, None);
                hole = cursor;
            }
            cursor = (cursor + 1) % CHILD_CONTENT_SLOTS;
        }
        Ok(Self { root: (next.len != 0).then(|| std::sync::Arc::new(next)) })
    }

    /// 🪪 Stable identity of the immutable child-resolution root retained by one job request.
    pub fn identity_digest(&self) -> u64 {
        let Some(root) = self.root.as_deref() else { return 0xcbf2_9ce4_8422_2325 };
        let mut digest = 0xcbf2_9ce4_8422_2325_u64;
        for entry in root.pages.iter().flatten().flat_map(|page| page.entries.iter().flatten()) {
            for byte in entry
                .slot
                .bytes()
                .chain(std::iter::once(0xff))
                .chain(entry.child_id.bytes())
                .chain(std::iter::once(0xfe))
                .chain(entry.dialect.artifact_kind.bytes())
                .chain(std::iter::once(0xfd))
                .chain(entry.dialect.standard.bytes())
                .chain(std::iter::once(0xfc))
                .chain(entry.dialect.subset.bytes())
                .chain(entry.revision)
            {
                digest = (digest ^ u64::from(byte)).wrapping_mul(0x1000_0000_01b3);
            }
        }
        digest
    }

    fn contains_entry_owner(&self, entry: &std::sync::Arc<ChildContentEntry>) -> bool {
        self.find(&entry.slot, &entry.child_id).ok().flatten().is_some_and(|candidate| std::ptr::eq(candidate, entry.as_ref()))
    }

    fn take_one(&mut self, current: &ChildContentView, owners: &ChildContentOwners) -> ChildContentTake {
        let Some(root) = self.root.take() else { return ChildContentTake::Complete };
        let mut root = match std::sync::Arc::try_unwrap(root) {
            Ok(root) => root,
            Err(shared) => {
                self.root = Some(shared);
                return ChildContentTake::Blocked;
            }
        };
        for page_index in 0..CHILD_CONTENT_PAGES {
            let Some(page) = root.pages[page_index].take() else { continue };
            let mut page = match std::sync::Arc::try_unwrap(page) {
                Ok(page) => page,
                Err(shared) => {
                    let retained_by_owner = ChildContentOwners::view_retains_page(current, page_index, &shared) || owners.retains_page(page_index, &shared);
                    if !retained_by_owner {
                        root.pages[page_index] = Some(shared);
                        self.root = Some(std::sync::Arc::new(root));
                        return ChildContentTake::Blocked;
                    }
                    let shared_entries = shared.entries.iter().flatten().count();
                    drop(shared);
                    root.len = root.len.saturating_sub(shared_entries);
                    self.root = (root.len != 0).then(|| std::sync::Arc::new(root));
                    return ChildContentTake::ReleasedShared;
                }
            };
            for entry_index in 0..CHILD_CONTENT_PAGE_SLOTS {
                let Some(entry) = page.entries[entry_index].take() else { continue };
                return match std::sync::Arc::try_unwrap(entry) {
                    Ok(entry) => {
                        root.len = root.len.saturating_sub(1);
                        if page.entries.iter().any(Option::is_some) {
                            root.pages[page_index] = Some(std::sync::Arc::new(page));
                        }
                        self.root = (root.len != 0).then(|| std::sync::Arc::new(root));
                        ChildContentTake::Snapshot(entry)
                    }
                    Err(shared) => {
                        if current.contains_entry_owner(&shared) || owners.retains_entry(&shared) {
                            drop(shared);
                            root.len = root.len.saturating_sub(1);
                            if page.entries.iter().any(Option::is_some) {
                                root.pages[page_index] = Some(std::sync::Arc::new(page));
                            }
                            self.root = (root.len != 0).then(|| std::sync::Arc::new(root));
                            ChildContentTake::ReleasedShared
                        } else {
                            page.entries[entry_index] = Some(shared);
                            root.pages[page_index] = Some(std::sync::Arc::new(page));
                            self.root = Some(std::sync::Arc::new(root));
                            ChildContentTake::Blocked
                        }
                    }
                };
            }
            self.root = (root.len != 0).then(|| std::sync::Arc::new(root));
            return ChildContentTake::ReleasedShared;
        }
        ChildContentTake::Complete
    }

    /// 🪞️ The same immutable root with one child's `snapshot` read in its place — a history edit's preview of a composed
    /// member (design §12), never the published root.
    pub(crate) fn with_member_read(&self, slot: &str, child_id: &str, dialect: &ArtifactDialect, revision: [u8; 32], snapshot: store::ErasedSnapshotRead) -> Result<Self, Fault> {
        let index = self.admit_member(slot, child_id)?;
        Ok(self.insert_entry_admitted(index, ChildContentEntry { slot: slot.to_string(), child_id: child_id.to_string(), dialect: dialect.clone(), revision, snapshot }))
    }

    async fn with_member<M: SpaceMember>(&self, slot: &str, child_id: &str, dialect: &ArtifactDialect, member: &M) -> Result<Self, Fault> {
        let index = self.admit_member(slot, child_id)?;
        self.capture_member_admitted(index, slot, child_id, dialect, member).await
    }

    async fn capture_member_admitted<M: SpaceMember>(&self, index: usize, slot: &str, child_id: &str, dialect: &ArtifactDialect, member: &M) -> Result<Self, Fault> {
        let revision = member.content_revision().await;
        let snapshot = member.snapshot_read_erased().await.map_err(|error| plugin_sdk_fault(error.to_string()))?;
        Ok(self.insert_entry_admitted(index, ChildContentEntry { slot: slot.to_string(), child_id: child_id.to_string(), dialect: dialect.clone(), revision, snapshot }))
    }

    /// 🧬️ Fixed-size, restart-stable identity paired with the captured child snapshot.
    pub fn revision(&self, slot: &str, child_id: &str) -> Result<[u8; 32], Fault> {
        self.find(slot, child_id)?.map(|entry| entry.revision).ok_or_else(|| plugin_sdk_fault(format!("no live child store for slot {slot} child {child_id}")))
    }

    /// 🧵️ Selects an immutable child snapshot capability without exposing concrete ownership.
    pub fn typed_read<S: ArtifactPack + Send + Sync + 'static>(&self, slot: &str, child_id: &str) -> Result<store::SnapshotReadRef<'_, S>, Fault> {
        let snapshot = &self.find(slot, child_id)?.ok_or_else(|| plugin_sdk_fault(format!("no live child store for slot {slot} child {child_id}")))?.snapshot;
        snapshot.typed::<S>().ok_or_else(|| plugin_sdk_fault(format!("child snapshot type mismatch for slot {slot} child {child_id}")))
    }

    /// 🎯️ The dialect a child materializes as, for a caller that must route by kind.
    pub fn dialect(&self, slot: &str, child_id: &str) -> Option<ArtifactDialect> {
        self.find(slot, child_id).ok().flatten().map(|entry| entry.dialect.clone())
    }

    /// 📋️ Every `(slot, child_id)` currently live under this document.
    pub fn slots(&self) -> Vec<(String, String)> {
        let Some(root) = self.root.as_deref() else { return Vec::new() };
        let mut slots = Vec::with_capacity(root.len);
        for index in 0..CHILD_CONTENT_SLOTS {
            if let Some(entry) = Self::entry_at(root, index) {
                slots.push((entry.slot.clone(), entry.child_id.clone()));
            }
        }
        slots
    }

    /// 🈳️ Whether this document has any live children at all.
    pub fn is_empty(&self) -> bool {
        self.root.as_ref().is_none_or(|root| root.len == 0)
    }
}

enum ChildContentTake {
    Blocked,
    ReleasedShared,
    Snapshot(ChildContentEntry),
    Complete,
}

/// 👑️ Every OTHER bounded owner of a retained child-content page during one disposal step: the
/// pending sibling retirements of the same registry. The live root is passed separately. A page or
/// entry alias held by an owner is handed over — the owner that ends up exclusive retires it — while
/// an alias held by a mere borrower (an operation view a job still holds) blocks, because a borrower
/// drops without a bounded disposer. Copy-on-write publication makes two consecutive retirements
/// share every untouched page, so without this set both wait on each other forever.
pub(crate) struct ChildContentOwners {
    views: [ChildContentView; ARTIFACT_LIVE_OUTPUT_SLOTS],
    len: usize,
}

impl ChildContentOwners {
    /// 🈳️ The owner set of a retirement with no live sibling.
    fn none() -> Self {
        Self { views: std::array::from_fn(|_| ChildContentView::EMPTY), len: 0 }
    }

    fn push(&mut self, view: ChildContentView) {
        assert!(self.len < ARTIFACT_LIVE_OUTPUT_SLOTS, "child-content owner set exceeds the fixed retirement registry");
        self.views[self.len] = view;
        self.len += 1;
    }

    fn view_retains_page(view: &ChildContentView, page_index: usize, page: &std::sync::Arc<ChildContentPage>) -> bool {
        view.root.as_deref().and_then(|root| root.pages[page_index].as_ref()).is_some_and(|candidate| std::sync::Arc::ptr_eq(candidate, page))
    }

    fn retains_page(&self, page_index: usize, page: &std::sync::Arc<ChildContentPage>) -> bool {
        self.views[..self.len].iter().any(|view| Self::view_retains_page(view, page_index, page))
    }

    fn retains_entry(&self, entry: &std::sync::Arc<ChildContentEntry>) -> bool {
        self.views[..self.len].iter().any(|view| view.contains_entry_owner(entry))
    }
}

impl<M> ArtifactFixedRegistry<ChildMemberRetirement<M>> {
    /// 🍂️ Whether one exact child identity is still retiring (its member has not closed yet).
    fn retains_member(&self, slot: &str, child_id: &str) -> bool {
        (0..ARTIFACT_LIVE_OUTPUT_SLOTS).any(|index| self.entry(index).is_some_and(|(_, retirement)| retirement.retires(slot, child_id)))
    }

    /// 🍂️ The member of one exact retiring child — the disposer of the snapshot leases retired roots still hold.
    fn retiring_member_mut(&mut self, slot: &str, child_id: &str) -> Option<&mut M> {
        let id = (0..ARTIFACT_LIVE_OUTPUT_SLOTS).find_map(|index| self.entry(index).and_then(|(id, retirement)| retirement.retires(slot, child_id).then_some(*id)))?;
        self.get_mut(id)?.entry.as_mut().map(|entry| &mut entry.member)
    }
}

/// 🪪️ The member that disposes one child snapshot lease: the live member, else the retiring member of a child
/// its coordinate left while a retired root still lent its snapshot.
fn child_snapshot_owner<'a, M>(children: &'a mut ChildMemberRegistry<M>, retiring: Option<&'a mut ArtifactFixedRegistry<ChildMemberRetirement<M>>>, slot: &str, child_id: &str) -> Option<&'a mut M> {
    if let Some(entry) = children.get_mut(&(slot.to_string(), child_id.to_string())) {
        return Some(&mut entry.member);
    }
    retiring?.retiring_member_mut(slot, child_id)
}

impl ArtifactFixedRegistry<ChildContentRetirement> {
    /// 👥️ The views of every pending child-root retirement except the one about to take a step.
    fn sibling_content_owners(&self, stepping: u64) -> ChildContentOwners {
        let mut owners = ChildContentOwners::none();
        for index in 0..ARTIFACT_LIVE_OUTPUT_SLOTS {
            if let Some((id, retirement)) = self.entry(index) {
                if *id != stepping {
                    owners.push(ChildContentView::clone(&retirement.view));
                }
            }
        }
        owners
    }
}

pub(crate) struct ChildContentRetirement {
    view: std::mem::ManuallyDrop<ChildContentView>,
    pub(crate) pending: std::mem::ManuallyDrop<Option<ChildContentEntry>>,
    active: std::mem::ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,
    active_member: std::mem::ManuallyDrop<Option<(String, String)>>,
    require_member_terminal: bool,
}

impl ChildContentRetirement {
    fn new(view: ChildContentView, require_member_terminal: bool) -> Self {
        Self { view: std::mem::ManuallyDrop::new(view), pending: std::mem::ManuallyDrop::new(None), active: std::mem::ManuallyDrop::new(None), active_member: std::mem::ManuallyDrop::new(None), require_member_terminal }
    }

    /// 🪪️ A nested disposer's refusal is a NAMED law violation, not an anonymous internal
    /// error: the store's own `ReturnedSnapshotReadRetirement` polices exactly the
    /// invariant `interactive-job.child-snapshot-terminal-not-empty` below polices, but
    /// the erased trait can only answer with a `String`, so reporting it as
    /// `plugin.internal` erased which law was broken from every instrument that reads
    /// fault codes.
    fn close_step<M: SpaceMember>(
        &mut self,
        children: &mut ChildMemberRegistry<M>,
        retiring: Option<&mut ArtifactFixedRegistry<ChildMemberRetirement<M>>>,
        current: &ChildContentView,
        owners: &ChildContentOwners,
        maximum_items: usize,
        maximum_bytes: usize,
    ) -> Result<PluginCloseStep, Fault> {
        if maximum_items == 0 {
            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(active) = self.active.as_mut() {
            return match active
                .close_step(maximum_items, maximum_bytes)
                .map_err(|reason| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-snapshot-disposer-refused"), format!("child snapshot disposer refused its own bounded step: {reason}")))?
            {
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                store::SnapshotRetirementStep::Pending { .. } => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-snapshot-retirement-over-budget"), "child snapshot disposer exceeded its exact item or byte grant")),
                store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "child snapshot disposer is waiting on external ownership" }),
                store::SnapshotRetirementStep::Complete => {
                    if !active.terminal_is_empty() {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-snapshot-terminal-not-empty"), "child snapshot disposer reported Complete without its exact terminal-empty witness"));
                    }
                    drop(self.active.take());
                    if !self.require_member_terminal {
                        drop(self.active_member.take());
                    }
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
            };
        }
        if let Some((slot, child_id)) = self.active_member.as_ref() {
            let Some(member) = child_snapshot_owner(children, retiring, slot, child_id) else {
                return Ok(PluginCloseStep::Blocked { reason: "final child snapshot lease verification lost its exact live member owner" });
            };
            if let Some(owner) = member.take_returned_snapshot_read_retirement().map_err(|error| plugin_sdk_fault(error.to_string()))? {
                *self.active = Some(owner);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !member.snapshot_read_leases_terminal_is_empty() {
                return Ok(PluginCloseStep::Blocked { reason: "final child snapshot lease remains live outside the bounded return pump" });
            }
            drop(self.active_member.take());
            return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.pending.is_none() {
            match self.view.take_one(current, owners) {
                ChildContentTake::Blocked => return Ok(PluginCloseStep::Blocked { reason: "retired child root remains borrowed by an exact operation view" }),
                ChildContentTake::ReleasedShared => return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                ChildContentTake::Snapshot(entry) => *self.pending = Some(entry),
                ChildContentTake::Complete => {
                    let empty = std::mem::replace(&mut *self.view, ChildContentView::EMPTY);
                    drop(empty);
                    return Ok(PluginCloseStep::Complete);
                }
            }
        }
        let entry = self.pending.take().expect("pending child snapshot authority exists");
        let Some(member) = child_snapshot_owner(children, retiring, &entry.slot, &entry.child_id) else {
            *self.pending = Some(entry);
            return Ok(PluginCloseStep::Blocked { reason: "retired child snapshot has no exact live member disposer owner" });
        };
        let ChildContentEntry { slot, child_id, dialect, revision, snapshot } = entry;
        match member.retire_snapshot_read_erased(snapshot) {
            Ok(owner) => {
                *self.active_member = Some((slot, child_id));
                drop(dialect);
                *self.active = Some(owner);
                Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
            }
            Err(rejected) => {
                *self.pending = Some(ChildContentEntry { slot, child_id, dialect, revision, snapshot: rejected.snapshot });
                Ok(PluginCloseStep::Blocked { reason: "child member has not installed its exact bounded snapshot retirement factory" })
            }
        }
    }

    fn terminal_is_empty(&self) -> bool {
        self.view.root.as_ref().is_none_or(|root| root.len == 0) && self.pending.is_none() && self.active.is_none() && self.active_member.is_none()
    }
}

impl Drop for ChildContentRetirement {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || self.terminal_is_empty(), "incomplete child-content retirement reached Drop without bounded disposal");
    }
}

struct SnapshotReadReturnPump {
    active: std::mem::ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,
}

impl SnapshotReadReturnPump {
    fn new() -> Self {
        Self { active: std::mem::ManuallyDrop::new(None) }
    }

    fn drive(&mut self, next: impl FnOnce() -> Result<Option<Box<dyn store::ErasedSnapshotRetirement>>, Fault>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
        if maximum_items == 0 {
            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(active) = self.active.as_mut() {
            return match active.close_step(maximum_items, maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))? {
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                store::SnapshotRetirementStep::Pending { .. } => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.snapshot-read-return-over-budget"), "returned snapshot-read disposer exceeded its exact item or byte grant")),
                store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "returned snapshot-read disposer is waiting on external ownership" }),
                store::SnapshotRetirementStep::Complete => {
                    if !active.terminal_is_empty() {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.snapshot-read-return-terminal-not-empty"), "returned snapshot-read disposer reported Complete without its exact terminal-empty witness"));
                    }
                    drop(self.active.take());
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
            };
        }
        match next()? {
            Some(owner) => {
                *self.active = Some(owner);
                Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
            }
            None => Ok(PluginCloseStep::Complete),
        }
    }

    fn terminal_is_empty(&self) -> bool {
        self.active.is_none()
    }
}

impl Drop for SnapshotReadReturnPump {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || self.terminal_is_empty(), "returned snapshot-read pump reached Drop before its exact disposer was terminal-empty");
    }
}

