/// 🐁️ The ephemeral, never-persisted half of the interaction mechanism — `VcsArtifactApp`'s hover
/// map, one `DomainHover` per domain (mirrors `protocol::InteractionState.hover`'s own shape; see
/// that field's doc for why one slot per domain, not per channel). Deliberately a plain type alias,
/// not a generic `TransientStore<P, M>` instance: hover here is applied directly by the interaction
/// dispatch interception, never through an app's own `Emit`/ephemeral lane, so the `Mutation`-trait
/// machinery `TransientStore` requires would be unused ceremony.
pub type InteractionHoverState = BTreeMap<String, protocol::DomainHover>;

pub use crate::local_interaction::mutations::{InteractionConfigMutation, SetInteractionState};

impl InteractionConfigMutation {
    pub fn set_state(state: protocol::InteractionState) -> Self {
        Self::SetInteractionState(SetInteractionState { state })
    }
}

/// 🕹️ `MutationDiff`'s supertrait bound — a "no-op" default, never dispatched as a real mutation
/// (only `apply`/`absorb` are ever called on a diff value; a `Self::Diff` is never itself the
/// starting point of a fresh mutation).
impl Default for InteractionConfigMutation {
    fn default() -> Self {
        InteractionConfigMutation::set_state(protocol::InteractionState::default())
    }
}

impl ::protocol::MutationDiff<protocol::InteractionState> for InteractionConfigMutation {
    fn apply(&self, _base: &protocol::InteractionState) -> protocol::MutationApplyResult<protocol::InteractionState> {
        let InteractionConfigMutation::SetInteractionState(state) = self;
        state.apply()
    }
    fn absorb(&mut self, other: Self) {
        *self = other;
    }
}

impl ::protocol::OpText for InteractionConfigMutation {
    fn print_op(&self) -> String {
        let InteractionConfigMutation::SetInteractionState(state) = self;
        format!("set-interaction-state {}", semio_framework_pack_json::to_json_string(state))
    }
    fn parse_op(line: &str) -> Result<Self, ::semio_framework_diagnostic::TextError> {
        let body = line
            .strip_prefix("set-interaction-state ")
            .ok_or_else(|| ::semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue, format!("unknown interaction config op '{line}'"), ::semio_framework_diagnostic::TextSpan::at(1, 1)))?;
        let state: protocol::InteractionState = semio_framework_pack_json::from_json_str(body, semio_framework_pack_json::JsonMemberPolicy::Reject)
            .map_err(|error| ::semio_framework_diagnostic::TextError::from_value_error(error, ::semio_framework_diagnostic::TextSpan::at(1, 1)))?;
        Ok(InteractionConfigMutation::set_state(state))
    }
}

impl ::protocol::OpBinary for InteractionConfigMutation {
    fn encode_op(&self) -> Result<Vec<u8>, ::protocol::ProtocolError> {
        let InteractionConfigMutation::SetInteractionState(state) = self;
        Ok(semio_framework_pack_json::to_json_string(state).into_bytes())
    }
    fn decode_op(bytes: &[u8]) -> Result<Self, ::protocol::ProtocolError> {
        let text = std::str::from_utf8(bytes).map_err(|error| ::protocol::ProtocolError::Malformed { what: "interaction-config-mutation", offset: 0, detail: error.to_string() })?;
        let state: protocol::InteractionState = semio_framework_pack_json::from_json_str(text, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|error| ::protocol::ProtocolError::Malformed {
            what: "interaction-config-mutation",
            offset: 0,
            detail: error.to_string(),
        })?;
        Ok(InteractionConfigMutation::set_state(state))
    }
}
