//#region 🔖️CommandLog
/// 🎚️ Tri-state mutations filter of the framework history panel — `All` is the default.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum HistoryCommandFilter {
    #[default]
    All,
    WithoutMutations,
    OnlyMutations,
}

impl HistoryCommandFilter {
    /// 🎚️ Every filter, in the order `setHistoryCommandFilter` declares its options.
    pub const ALL: [Self; 3] = [Self::All, Self::WithoutMutations, Self::OnlyMutations];

    /// 🔖️ The one wire value of this filter: the `setHistoryCommandFilter` option it is declared as and the
    /// `HistoryPatch.commandFilter` it is projected as.
    pub fn value(self) -> &'static str {
        match self {
            Self::All => semio_framework::HISTORY_COMMAND_FILTER_ALL,
            Self::WithoutMutations => semio_framework::HISTORY_COMMAND_FILTER_WITHOUT_MUTATIONS,
            Self::OnlyMutations => semio_framework::HISTORY_COMMAND_FILTER_ONLY_MUTATIONS,
        }
    }

    /// 🔎️ The filter a declared option `value` names; `None` for any other value.
    pub fn from_value(value: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|filter| filter.value() == value)
    }
}

/// ⏪️ A stored, replayable inverse for a `View`/`🐚️Shell`-kind command — the memory-only
/// counterpart to a VCS edit's `Mutation::inverse`. `action_id` is a plugin action id (`View` rows —
/// replayed locally via `dispatch_action`) or a shell command id (`🐚️Shell` rows — bubbled out as
/// `Effect::ReplayShellCommand` since the plugin has no access to shell-owned state). Never
/// persisted: it lives only on the in-memory `CommandLogEntry`/`CommandView`.
#[derive(Clone, Debug, PartialEq)]
pub struct InverseAction {
    pub action_id: String,
    pub args: Option<DslValue>,
}

/// ⏪️ One undone shell row waiting on the redo stack — chrome-order counterpart to VCS redo.
struct ShellHistoryReplay {
    seq: u64,
    redo: InverseAction,
}

/// 🗝️ What a backfilled command-log row references: a document edit (with the verb that authored it) or a
/// `Supersede` history transition.
enum CommandLogAppendKey {
    Edit { edit_id: String, verb: Option<String>, child_edit_ids: Vec<String> },
    Members { edit_ids: Vec<String> },
    Transition(String),
}

/// 🧭️ What a cached [`HistoryView`] was built against (design §20.14): the document's and every composed member's
/// [`time_travel::HistoryStoreStamp`], the newest command-log row and the row count it held, its shell rows and their
/// undone count, and the supersede records — what lets the next refresh rebuild only the rows a change touched.
#[derive(Clone, Debug, Default, PartialEq)]
pub(crate) struct HistoryViewStamp {
    document: time_travel::HistoryStoreStamp,
    members: Vec<(String, time_travel::HistoryStoreStamp)>,
    newest_seq: u64,
    rows: usize,
    inverse_rows: usize,
    shell_undone: usize,
    supersede_records: usize,
}

/// 🗂️ The history view a refresh patches in place, with the stamp it was built against; the projection cache shares it.
pub(crate) struct HistoryViewCache {
    view: std::sync::Arc<HistoryView>,
    stamp: HistoryViewStamp,
}

/// 🩹️ The rows one refresh rebuilds in a cached [`HistoryView`]: the log rows from `fresh_from` on are new, `rebuild`
/// names the held rows a change touched, `positions` the applied position of every document edit it touched.
struct HistoryViewPatch {
    fresh_from: usize,
    rebuild: BTreeSet<u64>,
    positions: Vec<(String, Option<usize>)>,
}

/// 🧾️ How far the command log is proven to reference every edit (`backfill_command_log`): the document ledger's length
/// and its last edit id, each composed member ledger's, the supersede records, and the newest row at that moment — the
/// next backfill reads only what came after (design §20.14).
#[derive(Clone, Debug, Default, PartialEq)]
pub(crate) struct HistoryBackfillMark {
    edits: usize,
    last_edit: Option<String>,
    members: Vec<(String, usize, Option<String>)>,
    supersede_records: usize,
    log_seq: u64,
}

#[cfg(test)]
thread_local! {
    /// 🧮️ History rows built on this test thread — what the O(change) laws of the history view count (design §20.14).
    pub(crate) static HISTORY_ROWS_BUILT: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

/// 📚️ What the history rows of one build or patch read beyond their command-log entries: the applied position of the
/// edits it knows (`full`: every applied edit, so an unknown one is not applied), the edits by id (`full` only; a patch
/// reads the ledger's tail), the previous projection of each row and its labels, the composed members' edits, the
/// members' applied tails, the history edits in effect and the app instance id.
struct HistoryRowReads<'a, Mu> {
    full: bool,
    positions: HashMap<&'a str, Option<usize>>,
    edits: HashMap<&'a str, &'a protocol::Edit<Mu>>,
    previous: HashMap<u64, &'a CommandView>,
    labelled: HashMap<&'a str, &'a MutationView>,
    members: HashMap<String, time_travel::MemberEditHistory>,
    child_applied_tails: HashSet<String>,
    applied_entries: HashSet<usize>,
    app_id: String,
}

/// 🏷️ A backfilled edit row's label: the registry label of the verb that authored it, else its first operation's label
/// `first` (a document leaf's localized `SemanticMutation::label`) — the rule a live row records; an edit without
/// operations is named by its id. An edit's stored description is never a label (design §20.6).
fn backfilled_edit_label<Mu>(edit: &protocol::Edit<Mu>, verb_label: Option<LocalizedLabel>, first: impl FnOnce(&Mu) -> LocalizedLabel) -> LocalizedLabel {
    verb_label.unwrap_or_else(|| edit.forwards.first().map_or_else(|| LocalizedLabel::data(edit.id.clone()), first))
}

/// 🧾️ Inputs for one appended session command before its sequence and timestamp are assigned.
struct CommandLogAppend<'a> {
    action_id: &'a str,
    label: LocalizedLabel,
    kind: ActionKind,
    edit_id: Option<String>,
    transition_id: Option<String>,
    timestamp: Option<String>,
    inverse: Option<InverseAction>,
}

/// 🧾️ One appended session-command record — runtime-only, never persisted (the VCS envelope
/// is the persisted half; see `CommandView::op_lines`, derived live from `envelope.vcs.edits`).
/// Append-only: `VcsArtifactApp` only ever pushes to `command_log`, including for undo/redo.
#[derive(Clone, Debug, PartialEq)]
pub struct CommandLogEntry {
    pub seq: u64,
    pub action_id: String,
    pub label: LocalizedLabel,
    pub kind: ActionKind,
    pub timestamp: String,
    /// 🔗️ Set iff this command created/amended a DOCUMENT VCS edit — `None` for pure cursor motion (undo/redo/revert).
    /// A config-lane edit is never a history row (design §20.13, L4), so no row carries one and a config-only dispatch
    /// records nothing.
    pub edit_id: Option<String>,
    /// 🧩️ UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM (C1): every CHILD document edit id this command's composite `dispatch_group`
    /// call produced — one entry per touched CHILD member of a single group dispatch (never folded — a group dispatch
    /// always issues a plain `Apply`, see `Emit::child_emits`'s own doc comment).
    pub child_edit_ids: Vec<String>,
    /// ✏️ Set iff this row is a `Supersede` history transition of the DOCUMENT store's event log (a history edit, or
    /// the undo or redo of one) — backfilled from the transitions, never from a live dispatch, so local, remote and
    /// reloaded history edits are rows alike (`VcsArtifactApp::backfill_command_log`).
    pub transition_id: Option<String>,
    /// 🔢️ How many consecutive identical `View`/`🐚️Shell` dispatches folded into this one row —
    /// see `VcsArtifactApp::record_command`. Always `1` for `Mutation`/`History`/`Clipboard` entries
    /// and for anything carrying an `edit_id`, which never fold.
    pub count: u32,
    /// ⏪️ A real inverse for a `🐚️Shell`-kind row with no `edit_id`
    /// (`noteShellCommand`-authored — shell-owned state this plugin cannot touch itself) — see
    /// `InverseAction`. `None` means this row has no working inverse (not just unauthored/foreign),
    /// which is the normal case for chrome the shell notes without declaring `inverseCommandId`
    /// (window activation/resize/move): such a row is logged but is never an undo target, so `undo`
    /// reaches the user's own document edit instead of replaying chrome into the guest.
    pub inverse: Option<InverseAction>,
}

/// 🧾️ One row of the merged command+operation timeline handed to renderers — `CommandLogEntry`
/// plus everything derived live from the current `envelope.vcs.edits` state.
#[derive(Clone, Debug, PartialEq)]
pub struct CommandView {
    pub seq: u64,
    pub action_id: String,
    pub label: LocalizedLabel,
    pub kind: ActionKind,
    pub timestamp: String,
    pub edit_id: Option<String>,
    /// 🧩️ Verbatim `CommandLogEntry::child_edit_ids` — see that field's own doc comment.
    pub child_edit_ids: Vec<String>,
    /// ✏️ Verbatim `CommandLogEntry::transition_id`; such a row's label, `applied` and `revertible` derive from the
    /// supersede ledger (`SupersedeLedger`).
    pub transition_id: Option<String>,
    /// 🖋️ The actor who authored this row's document edit or history transition.
    pub author: Option<String>,
    /// 📜️ The LAST [`HISTORY_ROW_OPERATION_PREVIEW`] forward operations of this entry's edit, printed via
    /// `OpText::print_op`, newest last — a bounded preview, so reading the history costs the same per key at the end of a
    /// long coalesced typing run as at its start; empty for cursor-motion entries and for a dangling `edit_id` (document
    /// replaced mid-session).
    pub op_lines: Vec<String>,
    /// 🔢️ Forward operations of this entry's edit when `op_lines` was printed — a sealed row's preview is reused only while
    /// its edit still has exactly that many.
    pub op_count: usize,
    /// ✅️ The linked DOCUMENT edit is currently on the applied stack (`false` once undone) —
    /// `false` (not meaningful) for a row with no `edit_id`.
    pub applied: bool,
    /// ⏪️ Either (document edit-linked) `applied` AND authored by the local actor, (config
    /// edit-linked) the config edit is similarly applied+local, (child edit-linked) one of this
    /// row's `child_edit_ids` is a live child's TAIL applied edit, or (memory-only) this row
    /// carries a stored `inverse` — only these entries offer "inverse".
    pub revertible: bool,
    /// 🔢️ See `CommandLogEntry::count`.
    pub count: u32,
    /// ⏪️ See `CommandLogEntry::inverse`.
    pub inverse: Option<InverseAction>,
    /// 🛠️ The committed tool transaction this row's edit carries (`MutationMeta.transaction` of its first op).
    pub transaction: Option<protocol::TransactionRef>,
    /// ✏️ The applied mutations of this row's edit (at most [`HISTORY_ROW_MUTATION_ROWS`]), durable outcomes only;
    /// a history edit overlays its replay on them when projected.
    pub mutations: Vec<MutationView>,
}

/// ✏️ One applied mutation of a history row: its replica-independent id, applied position and index in its edit,
/// localized label (of its effective input), durable outcome and supersession state, and whether history editing
/// may replace its inputs.
#[derive(Clone, Debug, PartialEq)]
pub struct MutationView {
    pub mutation_id: String,
    pub position: u32,
    pub op_index: u32,
    pub label: LocalizedLabel,
    pub worst: Option<semio_framework_diagnostic::Severity>,
    pub messages: Vec<protocol::MutationMessage>,
    pub superseded: bool,
    pub withdrawn: bool,
    pub editable: bool,
    pub store: Option<String>,
}

/// 📜️ Operations a history row previews: its edit's newest ones (see `CommandView::op_lines`).
pub const HISTORY_ROW_OPERATION_PREVIEW: usize = 8;

/// 🏷️ A history row labelled by its edit's first leaf: the leaf's own localized label (`SemanticMutation::label`, resolved
/// at projection time so a reload keeps every locale), with `(+N)` for the edit's other operations.
// 🚫️async: a pure label composition.
pub fn history_leaf_row_label(leaf: &LocalizedLabel, op_count: usize) -> LocalizedLabel {
    let (leaf, more) = (leaf.clone(), op_count.saturating_sub(1));
    LocalizedLabel::from_fn(move |terminology, locale| {
        let first = leaf.resolve(terminology, locale);
        if more > 0 {
            format!("{first} (+{more})")
        } else {
            first.to_string()
        }
    })
}

/// ⏳️ The fault code every verb but a view or interaction verb answers while a whole-document load still runs (gap N17);
/// its en/de notice is the kernel's `history_notice("document.loading")`.
pub const DOCUMENT_LOADING_CODE: &str = "document.loading";

/// 🧱️ The code a refused adoption of this replica's own deferred history step reads by (its replay would leave Errors or
/// Fatals downstream); its en/de notice is the kernel's `history_notice("history.step-blocked")`.
pub const HISTORY_STEP_BLOCKED_CODE: &str = "history.step-blocked";

/// 🫥️ The fault code of a history verb, a history query or a history-carrying document lane on a head-only pure
/// evaluation (`📓️api-stepped-document-load.md` §4); its en/de notice is the kernel's
/// `history_notice("pure.history-unavailable")`.
pub const PURE_HISTORY_UNAVAILABLE_CODE: &str = "pure.history-unavailable";

/// 📚️ The framework's catalogue route: `setActiveExample` of an app that declares no such action loads the app's
/// catalogue document ([`ArtifactApp::catalogue_example_document`]).
pub const CATALOGUE_EXAMPLE_ACTION_ID: &str = "setActiveExample";

/// 🏷️ The framework's own label, in every shell locale, of a runtime verb no app declares (design §20.6): a history row
/// the runtime records for it never reads a hand-written description. `None` for every other verb.
// 🚫️async: a pure label lookup.
pub fn runtime_verb_label(verb: &str) -> Option<LocalizedLabel> {
    match verb {
        CATALOGUE_EXAMPLE_ACTION_ID => Some(LocalizedLabel::native("Load example", "Beispiel laden")),
        _ => None,
    }
}

/// 🎯️ The leaf label of a tool transaction's history row (design §19.1): the first of the edit's applied `ops` whose kind
/// the authoring `tool` declares as its intent ([`ArtifactApp::tool_intent_kinds`]), read from its mutation row in
/// `mutations` (its effective input) or labelled afresh when that row is windowed out; `None` when the tool declares no
/// kind any operation has, so the first leaf labels the row as before.
// 🚫️async: a pure lookup over the projected operations.
pub fn history_intent_label<A: ArtifactApp>(tool: &str, ops: &[&store::AppliedMutation<'_, A::Mutation>], mutations: &[MutationView]) -> Option<LocalizedLabel> {
    let intents = A::tool_intent_kinds(tool);
    let intent = ops.iter().take(if intents.is_empty() { 0 } else { ops.len() }).find(|op| intents.contains(&protocol::SemanticMutation::<A::Snapshot>::semantics(op.operation).kind))?;
    Some(mutations.iter().find(|row| row.mutation_id == intent.mutation_id.0).map_or_else(|| time_travel::time_travel_mutation_label::<A>(intent.operation), |row| row.label.clone()))
}

/// 🙈️ Whether a dispatch of `kind` is a history row: never an interaction verb, and a `View` only when it edited a
/// store (`edited`) or carries an inverse — a pure view verb changes no history and undo cannot reach it.
// 🚫️async: a pure total predicate over the dispatch's own facts.
pub fn history_row_is_recorded(kind: ActionKind, edited: bool, inverse: bool) -> bool {
    match kind {
        ActionKind::Interaction => false,
        ActionKind::View => edited || inverse,
        ActionKind::Mutation | ActionKind::History | ActionKind::Clipboard | ActionKind::Shell => true,
    }
}

/// 📜️ Checkpoint/alternative history summary for this viewer — the swimlane columns, the
/// undo/redo availability, this viewer's head, and the merged command+operation timeline.
/// `active_alternative_id` and `current_checkpoint_id` are this replica's head. `alternatives`
/// stays the shared registration. Built once per store generation.
#[derive(Clone, Debug, PartialEq)]
pub struct HistoryView {
    pub columns: Vec<HistoryColumn>,
    pub can_undo: bool,
    pub can_redo: bool,
    /// 👁 The alternative this viewer is on. `None` is the canonical trunk.
    pub active_alternative_id: Option<String>,
    /// 🌿️ Every alternative of the artifact's history, in declaration order ([`history_alternative_views`]).
    pub alternatives: Vec<AlternativeView>,
    /// 👁 The checkpoint this viewer is looking at: the tip of the active line, or an explicit checkout.
    pub current_checkpoint_id: Option<String>,
    /// 📜️ The session command log merged with live VCS op-text, newest first. Every edit in
    /// `envelope.vcs.edits` is referenced by exactly one entry (see `VcsArtifactApp::backfill_command_log`).
    pub commands: Vec<CommandView>,
    pub command_filter: HistoryCommandFilter,
}

impl HistoryView {
    /// 🕳️ An empty view for hand-built test/fixture `ArtifactView`s that don't exercise history.
    pub fn empty() -> Self {
        Self { columns: Vec::new(), can_undo: false, can_redo: false, active_alternative_id: None, alternatives: Vec::new(), current_checkpoint_id: None, commands: Vec::new(), command_filter: HistoryCommandFilter::default() }
    }
}

/// 🌿️ One alternative of the artifact's history as the history body lists it: its id and name, whether it is the
/// current one, who branched it and when (its `Branch` transition's actor and HLC wall time as RFC 3339 UTC; `None`
/// when the log holds no branch of it) and whether history edits were kept as it (scoped `Supersede` transitions).
#[derive(Clone, Debug, PartialEq)]
pub struct AlternativeView {
    pub id: String,
    pub name: String,
    pub current: bool,
    pub author: Option<String>,
    pub branched_at: Option<String>,
    pub edited: bool,
}

/// 🧾️ One history transition as the alternatives list reads it: a branch naming its alternative, author and wall
/// time, or a supersession with its scope.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AlternativeFact<'a> {
    Branch { alternative_id: &'a str, actor: &'a str, physical_ms: u64 },
    Supersede { scope: Option<&'a str> },
}

/// 🌿️ The alternatives list of the history body over `(id, name)` pairs in declaration order (the trunk first, with the
/// empty name the history body localizes) and the log's `facts` in HLC order: current when it is the `active` line,
/// authored by the first branch naming it, edited when a supersession is scoped to it. Twin: `🧪️tests/🧪️history-alternatives/🟦️.ts` over `🧫️fixtures/🧫️history-alternatives/🔣️.json`.
// 🚫️async: a pure projection over already-decoded facts.
pub fn history_alternative_views<'a>(alternatives: impl IntoIterator<Item = (&'a str, &'a str)>, active: Option<&str>, facts: &[AlternativeFact<'_>]) -> Vec<AlternativeView> {
    alternatives
        .into_iter()
        .map(|(id, name)| {
            let branch = facts.iter().find_map(|fact| match fact {
                AlternativeFact::Branch { alternative_id, actor, physical_ms } if *alternative_id == id => Some((*actor, *physical_ms)),
                _ => None,
            });
            AlternativeView {
                id: id.to_string(),
                name: name.to_string(),
                current: active == Some(id),
                author: branch.map(|(actor, _)| actor.to_string()),
                branched_at: branch.map(|(_, physical_ms)| protocol::scalar::format_rfc3339_ms(i64::try_from(physical_ms).unwrap_or(i64::MAX))),
                edited: facts.iter().any(|fact| matches!(fact, AlternativeFact::Supersede { scope: Some(scope) } if *scope == id)),
            }
        })
        .collect()
}
